#pragma once
#include <Eigen/Dense>
// Constrained minimum-variance gain: motion uses all three pseudo observations;
// attitude and sensor bias use only the unchanged horizontal observations.
// The full PHt, H and noise are retained in the subsequent Joseph update.
// No covariance row is deleted and no innovation is relabeled as a sensor.
template<class Gain, class Cross, class Innovation>
void constrain_vertical_pseudo_gain(Gain& K, const Cross& PHt, const Innovation& S,
                                   int phi, int bg, int ba) {
    using T = typename Gain::Scalar;
    const Eigen::Matrix<T,2,2> Sxy = S.template topLeftCorner<2,2>();
    Eigen::LDLT<Eigen::Matrix<T,2,2>> ldlt(Sxy);
    for (int off : {phi,bg,ba}) {
        if (off < 0) continue;
        for (int i=off;i<off+3;++i) {
            const Eigen::Matrix<T,2,1> rhs = PHt.template block<1,2>(i,0).transpose();
            K.template block<1,2>(i,0) = ldlt.solve(rhs).transpose();
            K(i,2) = T(0);
        }
    }
}

