#pragma once
#include "kalman_common/GyroInterval.h"

/*
  Copyright (c) 2025-2026 Mikhail Grushinskiy

  Based on: https://github.com/thomaspasser/q-mekf
  MIT License, Copyright (c) 2023 Thomas Passer

  Full-matrix Kalman that with linear navigation states:
     v (3)   : velocity in world frame
     p (3)   : displacement/position in world frame
     S (3)   : integral of displacement (∫ p dt) — with zero pseudo-measurement for drift correction
     a_w (3) : latent world-frame inertial acceleration (NED)

  - The quaternion MEKF logic (time_update, measurement_update, partial updates, quaternion correction) is implemented.
  - The extended linear states are driven by a latent OU world-acceleration a_w
    (accelerometer input is used only in the measurement update).
  - Accelerometer and magnetometer inputs must be given in aerospace/NED (x north, y east, z down)
*/

#ifdef EIGEN_NON_ARDUINO
#include <Eigen/Dense>
#include <Eigen/Eigenvalues>
#else
#include <ArduinoEigenDense.h>
#endif

#include <limits>
#include <cmath>
#include <algorithm>

#include "kalman_ou_common/KalmanOUCoreMath.h"

namespace ocean_imu::kalman {

template <typename T = float, bool with_gyro_bias = true, bool with_accel_bias = true>
class Kalman3D_Wave_OU_III {

    // Base (att_err + optional gyro bias)
    static constexpr int BASE_N = with_gyro_bias ? 6 : 3;

    // Extended states: v(3), p(3), S(3), a_w(3) [+ b_acc(3)]
    static constexpr int EXT_ADD = 12
        + (with_accel_bias ? 3 : 0);

    static constexpr int NX = BASE_N + EXT_ADD;

    // Offsets (always defined)
    static constexpr int OFF_V   = BASE_N + 0;
    static constexpr int OFF_P   = BASE_N + 3;
    static constexpr int OFF_S   = BASE_N + 6;
    static constexpr int OFF_AW  = BASE_N + 9;

    static constexpr int OFF_BA  = with_accel_bias ? (BASE_N + 12) : -1;


    typedef Eigen::Matrix<T, 3, 1> Vector3;
    typedef Eigen::Matrix<T, BASE_N, BASE_N> MatrixBaseN;
    typedef Eigen::Matrix<T, NX, NX> MatrixNX;
    typedef Eigen::Matrix<T, 3, 3> Matrix3;

    // Fixed-size helpers for internal scratch
    typedef Eigen::Matrix<T, 12, 12> Matrix12;
    typedef Eigen::Matrix<T, 12,  1> Vector12;
    typedef Eigen::Matrix<T, BASE_N, 12> MatrixBaseN12;
    typedef Eigen::Matrix<T, NX,  3> MatrixNX3;

    static constexpr T STD_GRAVITY = T(9.80665);  // standard gravity acceleration m/s²
    static constexpr T tempC_ref = T(35.0); // Reference temperature for temperature related accel bias drift °C

  public:
    EIGEN_MAKE_ALIGNED_OPERATOR_NEW

    struct MeasDiag3 {
        Vector3 r = Vector3::Zero();   // residual
        Matrix3 S = Matrix3::Zero();   // innovation covariance
        T nis = std::numeric_limits<T>::quiet_NaN(); // r^T S^-1 r
        bool accepted = false;         // update actually applied?
    };

    const MeasDiag3& lastAccDiag() const noexcept { return last_acc_diag_; }
    const MeasDiag3& lastMagDiag() const noexcept { return last_mag_diag_; }

    // Constructor signatures preserved, additional defaults for linear process noise
    Kalman3D_Wave_OU_III(Vector3 const& sigma_a, Vector3 const& gyro_noise_density_rad_sqrt_s, Vector3 const& sigma_m,
                  T Pq0 = T(5e-4), T Pb0 = T(1e-6), T b0 = T(1e-11), T R_S_noise_var = T(1.5),
                  T gravity_magnitude = T(STD_GRAVITY));

    // Initialization / measurement API.  The initializers return false, with
    // no exception, when the input cannot define an attitude (non-finite or
    // near-zero vectors, field parallel to gravity) and leave the filter state
    // unchanged.
    bool initialize_from_acc_mag(Vector3 const& acc, Vector3 const& mag);
    bool initialize_from_acc(Vector3 const& acc);
    bool initialize_from_acc_preserve_yaw(Vector3 const& acc);
    bool initialize_from_attitude(Eigen::Quaternion<T> const& q_bw,
                                  T tilt_sigma_rad,
                                  T yaw_sigma_rad);
    static Eigen::Quaternion<T> quaternion_from_acc(Vector3 const& acc);

    // Set the world-frame magnetic reference vector used by the mag measurement model. Pass NED units.
    void set_mag_world_ref(const Vector3& B_world) {
        v2ref = B_world;    // keep µT magnitude
    }

    void set_gyro_sample_mode(ocean_imu::kalman::filter_detail::GyroSampleMode mode) { gyro_interval_.set_mode(mode); }
    void set_gyro_sample_period(T period) { gyro_interval_.set_sample_period(period); }
    void prime_gyro_sample(const Vector3& rate, T dt) { gyro_interval_.prime(rate, dt); }
    void time_update(Vector3 const& gyr, T Ts);

    // Measurement updates preserved (operate on extended state internally)
    void measurement_update_acc_only(Vector3 const& acc, T tempC = tempC_ref);
    void measurement_update_mag_only(Vector3 const& mag);

    // Extended-only API:
    // Apply zero pseudo-measurement on S (integral drift correction)
    void applyIntegralZeroPseudoMeas();

    // 3D pseudo-measurement on position p (world, NED):
    //   p_meas ≈ p (meters), with per-axis std sigma_meas.
    // This does a full 3x3 Joseph update on the position block and its cross-covariances. Can be used for GPS fusion
    void measurement_update_position_pseudo(const Vector3& p_meas, const Vector3& sigma_meas);

    // 3D pseudo-measurement on velocity v (world, NED):
    //   v_meas ≈ v (m/s), with per-axis std sigma_meas. Can be used for GPS fusion
    void measurement_update_velocity_pseudo(const Vector3& v_meas, const Vector3& sigma_meas);

    // 1D pseudo-measurement on vertical velocity only (world z, NED down):
    //   vz_meas ≈ v_z (m/s), with std sigma_meas. Can be used for GPS fusion
    void measurement_update_vert_velocity_pseudo(T vz_meas, T sigma_meas);

    // Accessors
    [[nodiscard]] Eigen::Quaternion<T> quaternion() const { return qref.conjugate(); }
    [[nodiscard]] MatrixBaseN covariance_base() const { return Pext.topLeftCorner(BASE_N, BASE_N); } // top-left block
    [[nodiscard]] MatrixNX covariance_full() const { return Pext; }     // full extended covariance

    // Boat attitude in the *physical* heeled frame B → W (NED).
    [[nodiscard]] Eigen::Quaternion<T> quaternion_boat() const {
        // Internal quaternion() = B'→W (un-heeled frame to world)
        const Eigen::Quaternion<T> q_WBprime = quaternion();

        // q_B'B = rotation that maps physical body B to un-heeled frame B'
        // Roll of -wind_heel about X: B'←B ("un-heel").
        const T half = -wind_heel_rad_ * T(0.5);
        const T c = std::cos(half);
        const T s = std::sin(half);
        const Eigen::Quaternion<T> q_BprimeB(c, s, 0, 0); // (w, x, y, z)

        // Composition: B→W = (B'→W) ∘ (B→B') = q_WB' * q_B'B
        return q_WBprime * q_BprimeB;
    }

    void set_quaternion_boat(const Eigen::Quaternion<T>& q_bw) {
        project_gyro_bias_();
        Eigen::Quaternion<T> q = q_bw;
        const T nq = q.norm();
        if (!(nq > T(1e-8))) return;
        q.normalize();

        const T half = -wind_heel_rad_ * T(0.5);
        const T c = std::cos(half);
        const T s = std::sin(half);
        const Eigen::Quaternion<T> q_BprimeB(c, s, 0, 0);
        const Eigen::Quaternion<T> q_BBprime = q_BprimeB.conjugate();

        const Eigen::Quaternion<T> q_WBprime = q * q_BBprime;
        qref = q_WBprime.conjugate();
        qref.normalize();
        xext.template segment<3>(0).setZero();
    }

    [[nodiscard]] Vector3 gyroscope_bias() const {
        if constexpr (with_gyro_bias) {
            return xext.template segment<3>(3);
        } else {
            return Vector3::Zero();
        }
    }

    [[nodiscard]] Vector3 get_acc_bias() const {
        if constexpr (with_accel_bias) {
            return xext.template segment<3>(OFF_BA);
        } else {
            return Vector3::Zero();
        }
    }

    bool acc_bias_updates_enabled() const  { return acc_bias_updates_enabled_; }

    void set_acc_bias_updates_enabled(bool en) {
        if (acc_bias_updates_enabled_ == en) return;
        if constexpr (with_accel_bias) {
            if (!en) {
                // Prevent BA from being driven by other updates via cross-cov
                Pext.template block<3,BASE_N>(OFF_BA, 0).setZero();
                Pext.template block<BASE_N,3>(0, OFF_BA).setZero();

                // Also decouple from linear block (optional but consistent)
                Pext.template block<3,12>(OFF_BA, OFF_V).setZero();
                Pext.template block<12,3>(OFF_V, OFF_BA).setZero();
            } else {
                // inflate P_ba logic
                auto Pba = Pext.template block<3,3>(OFF_BA, OFF_BA);
                const T target_var = sigma_bacc0_ * sigma_bacc0_;
                for (int i = 0; i < 3; ++i) Pba(i,i) = std::max(Pba(i,i), target_var);
                Pext.template block<3,3>(OFF_BA, OFF_BA) = Pba;
            }
        }
        acc_bias_updates_enabled_ = en;
    }

    // Velocity in world (NED)
    [[nodiscard]] Vector3 get_velocity() const {
        // velocity state at offset BASE_N
        return xext.template segment<3>(BASE_N);
    }

    // Position in world (NED)
    [[nodiscard]] Vector3 get_position() const {
        // position state at offset BASE_N+3
        return xext.template segment<3>(BASE_N + 3);
    }

    // Integral displacement in world (NED)
    [[nodiscard]] Vector3 get_integral_displacement() const {
        // integral of displacement state at offset BASE_N+6
        return xext.template segment<3>(BASE_N + 6);
    }

    // Latent OU world-acceleration a_w (world, NED)
    [[nodiscard]] Vector3 get_world_accel() const { return xext.template segment<3>(OFF_AW); }

    // Read the active model, including parameter smoothing and applied floors.
    [[nodiscard]] T get_aw_time_constant() const { return tau_aw; }
    [[nodiscard]] Vector3 get_aw_stationary_std() const {
        return Sigma_aw_stat.diagonal().cwiseMax(T(0)).cwiseSqrt();
    }
    [[nodiscard]] Vector3 get_RS_noise_std() const {
        return R_S.diagonal().cwiseMax(T(0)).cwiseSqrt();
    }

    // Tuning setters
	void set_aw_time_constant(T tau_seconds) {
	    if (param_rw_enabled_) { param_rw_update_tau_cmd_(tau_seconds); return; }
	    tau_aw = std::max(T(1e-3), tau_seconds);
	}

    void set_pseudo_update_period_s(T period_s) {
        if (!(period_s > T(0)) || !std::isfinite(period_s)) return;
        const T new_period = std::max(T(1e-4), period_s);
        pseudo_update_elapsed_s_ =
            ocean_imu::kalman::ou_detail::retarget_period_elapsed_progress_preserving(
                pseudo_update_elapsed_s_, new_period);
        pseudo_update_period_s_ = new_period;
    }

    [[nodiscard]] T get_pseudo_update_period_s() const { return pseudo_update_period_s_; }

    // OU stationary std [m/s²] for a_w (per axis)
    void set_aw_stationary_std(const Vector3& std_aw) {
        const Vector3 s = std_aw.cwiseAbs();
        Sigma_aw_stat = s.array().square().matrix().asDiagonal();
        aw_process_correlated_ = false;
    }

    // Accept a full 3×3 SPD stationary covariance for a_w.
    void set_aw_stationary_cov_full(const Matrix3& Sigma);

    // Set OU stationary covariance for world-acceleration a_w,
    // using per-axis standard deviations and an optional cross-axis correlation.
    //
    // Arguments:
    //   std_aw     : per-axis standard deviations [m/s²] for (x, y, z)
    //   rho_corr   : dimensionless correlation coefficient between horizontal
    //                and vertical accelerations
    //
    // Notes:
    //   • Negative rho_corr is appropriate for NED (z down), because when the
    //     surface moves upward (negative az), horizontal acceleration is forward.
    //   • Positive rho_corr fits ENU (z up).
    //   • The resulting covariance is projected to SPD for numerical stability.
    void set_aw_stationary_corr_std(const Vector3& std_aw, T rho_xz_corr = T(-0.65), T rho_yz_corr = T(-0.65)) {
        rho_xz_corr = std::max(T(-0.999), std::min(rho_xz_corr, T(0.999)));
        rho_yz_corr = std::max(T(-0.999), std::min(rho_yz_corr, T(0.999)));

        const T sx = std::max(T(1e-9), std::abs(std_aw.x()));
        const T sy = std::max(T(1e-9), std::abs(std_aw.y()));
        const T sz = std::max(T(1e-9), std::abs(std_aw.z()));

        Matrix3 S;
        S <<
            sx*sx, T(0), rho_xz_corr*sx*sz,
            T(0), sy*sy, rho_yz_corr*sy*sz,
            rho_xz_corr*sx*sz, rho_yz_corr*sy*sz, sz*sz;
        S = T(0.5) * (S + S.transpose());
        ocean_imu::kalman::ou_detail::regularize_psd_if_needed<T,3>(S);
        Sigma_aw_stat = S;
        aw_process_correlated_ = true;
    }

    void reset_aw_covariance_to_stationary() {
        for (int i = 0; i < NX; ++i) {
            if (i < OFF_AW || i >= OFF_AW + 3) {
                Pext.template block<3,1>(OFF_AW, i).setZero();
                Pext.template block<1,3>(i, OFF_AW).setZero();
            }
        }
        Pext.template block<3,3>(OFF_AW, OFF_AW) = Sigma_aw_stat;
        aw_covariance_floor_pending_ = false;
        symmetrize_Pext_();
    }

    // Select the a_w covariance synchronization policy. false (default) keeps
    // synchronization inside the next Kalman prediction as a positive-
    // semidefinite process-covariance increment. true selects immediate
    // P_awaw block replacement.
    void set_legacy_aw_covariance_replacement(bool on) {
        legacy_aw_covariance_replacement_ = on;
        if (on) aw_covariance_floor_pending_ = false;
    }
    [[nodiscard]] bool legacy_aw_covariance_replacement() const noexcept {
        return legacy_aw_covariance_replacement_;
    }

    // Request an a_w covariance floor at the current stationary OU covariance.
    // The default path queues the request and applies it inside the next
    // prediction as Delta = Pi_+(Sigma_aw_stat - P_awaw^-). Because the full
    // covariance increment is E_a Delta E_a^T >= 0, PSD and all existing cross-
    // covariances are preserved. With legacy_aw_covariance_replacement_
    // enabled, the posterior block is replaced immediately instead.
    void synchronize_aw_covariance_to_stationary() {
        if (legacy_aw_covariance_replacement_) {
            aw_covariance_floor_pending_ = false;
            Pext.template block<3,3>(OFF_AW, OFF_AW) = Sigma_aw_stat;
            symmetrize_Pext_();
            return;
        }
        aw_covariance_floor_target_ = T(0.5) * (Sigma_aw_stat + Sigma_aw_stat.transpose());
        aw_covariance_floor_pending_ = true;
    }

    // Reach the same stationary marginal through a congruence x_aw -> A x_aw
    // with A = L_new L_old^-1, where P_awaw = L_old L_old^T and
    // Sigma_aw_stat = L_new L_new^T.
    //
    // The congruence hits the target marginal exactly, leaves the
    // cross-covariance measured against the whitened a_w block unchanged, and
    // preserves positive semi-definiteness by construction. It is the
    // consistent reading of "re-align the marginal while keeping what the
    // filter has learned", and it is offered so that reading can be measured
    // rather than argued about.
    void synchronize_aw_covariance_to_stationary_congruent() {
        aw_covariance_floor_pending_ = false;
        Matrix3 P_aw = Pext.template block<3,3>(OFF_AW, OFF_AW);
        P_aw = T(0.5) * (P_aw + P_aw.transpose());

        Matrix3 Sigma = T(0.5) * (Sigma_aw_stat + Sigma_aw_stat.transpose());

        Eigen::LLT<Matrix3> llt_old(P_aw);
        Eigen::LLT<Matrix3> llt_new(Sigma);
        if (llt_old.info() == Eigen::Success && llt_new.info() == Eigen::Success) {
            const Matrix3 L_old = llt_old.matrixL();
            const Matrix3 L_new = llt_new.matrixL();

            bool factors_usable = true;
            for (int i = 0; i < 3; ++i) {
                if (!(L_old(i,i) > T(1e-12)) || !std::isfinite(L_old(i,i)) ||
                    !std::isfinite(L_new(i,i))) {
                    factors_usable = false;
                    break;
                }
            }

            if (factors_usable) {
                // A_transposed = L_old^-T L_new^T, so P_i,aw <- P_i,aw A^T.
                const Matrix3 A_transposed =
                    L_old.transpose().template triangularView<Eigen::Upper>()
                         .solve(L_new.transpose());

                if (A_transposed.allFinite()) {
                    for (int i = 0; i < NX; ++i) {
                        if (i >= OFF_AW && i < OFF_AW + 3) continue;
                        const Eigen::Matrix<T,1,3> scaled =
                            Pext.template block<1,3>(i, OFF_AW) * A_transposed;
                        Pext.template block<1,3>(i, OFF_AW) = scaled;
                        Pext.template block<3,1>(OFF_AW, i) = scaled.transpose();
                    }
                }
            }
        }

        Pext.template block<3,3>(OFF_AW, OFF_AW) = Sigma;
        symmetrize_Pext_();
    }

    // Covariances for ∫p dt pseudo-measurement
	void set_RS_noise(const Vector3& sigma_S) {
		if (param_rw_enabled_) { param_rw_update_sigma_S_cmd_(sigma_S); return; }
		R_S = sigma_S.array().square().matrix().asDiagonal();
		R_S = T(0.5) * (R_S + R_S.transpose());
	}

	void set_RS_noise_matrix(const Matrix3& R) {
	    Matrix3 S = T(0.5) * (R + R.transpose());
	    ocean_imu::kalman::ou_detail::project_psd_ou_iii<T,3>(S, T(1e-8));

	    if (param_rw_enabled_) {
	        Vector3 sig;
	        sig.x() = std::sqrt(std::max(T(0), S(0,0)));
	        sig.y() = std::sqrt(std::max(T(0), S(1,1)));
	        sig.z() = std::sqrt(std::max(T(0), S(2,2)));
	        param_rw_update_sigma_S_cmd_(sig);
	        return;
	    }
	    R_S = S;
	}

    // Accelerometer measurement noise (std in m/s² per axis)
	void set_Racc_std(const Vector3& sigma_acc) {
	    if (param_rw_enabled_) { param_rw_update_sigma_acc_cmd_(sigma_acc); return; }
	    Racc = sigma_acc.array().square().matrix().asDiagonal();
	}

    // Magnetometer measurement noise (std per axis, μT or unitless)
    void set_Rmag(const Vector3& sigma_mag) {
        Rmag = sigma_mag.array().square().matrix().asDiagonal();
    }

    void set_initial_linear_uncertainty(T sigma_v0, T sigma_p0, T sigma_S0) {
        Pext.template block<3,3>(OFF_V, OFF_V) = Matrix3::Identity() * (sigma_v0 * sigma_v0);   // v (3)
        Pext.template block<3,3>(OFF_P, OFF_P) = Matrix3::Identity() * (sigma_p0 * sigma_p0);   // p (3)
        Pext.template block<3,3>(OFF_S, OFF_S) = Matrix3::Identity() * (sigma_S0 * sigma_S0);   // S (3)
    }

    void set_initial_acc_bias_std(T s) {
        if constexpr (with_accel_bias) {
            sigma_bacc0_ = std::max(T(0), s);
            Pext.template block<3,3>(OFF_BA, OFF_BA) = Matrix3::Identity() * sigma_bacc0_ * sigma_bacc0_;
        }
    }

    // Despite the method name, the supplied quantity is interpreted as
    // the continuous driving-noise density of the residual accelerometer-bias
    // OU process. For h << tau_b this preserves the former random-walk
    // covariance increment Q_bacc_ * h.
    void set_Q_bacc_rw(const Vector3& driving_std_per_sqrt_s) {
        if constexpr (with_accel_bias)
            Q_bacc_ = driving_std_per_sqrt_s.array().square().matrix().asDiagonal();
    }

    // Slow first-order Gauss--Markov model for the residual bias beta_a in
    //   b_a(T) = k_a (T - tempC_ref) + beta_a.
    // The temperature-calibrated mean is deterministic; only beta_a is an
    // estimated stochastic state and mean-reverts toward zero.
    void set_acc_bias_time_constant(T tau_seconds) {
        if constexpr (with_accel_bias)
            tau_bacc_ = std::max(T(1e-3), tau_seconds);
    }
    [[nodiscard]] T get_acc_bias_time_constant() const noexcept { return tau_bacc_; }

    void set_acc_bias_ou_stationary_std(const Vector3& stationary_std, T tau_seconds) {
        if constexpr (with_accel_bias) {
            set_acc_bias_time_constant(tau_seconds);
            const Vector3 s = stationary_std.cwiseAbs();
            Q_bacc_ = (T(2) / tau_bacc_) * s.array().square().matrix().asDiagonal();
        }
    }

    [[nodiscard]] Vector3 get_acc_bias_at_temperature(T tempC) const {
        if constexpr (with_accel_bias) {
            return xext.template segment<3>(OFF_BA) + k_a_ * (tempC - tempC_ref);
        }
        return Vector3::Zero();
    }

    // Bias used by the measurement model, expressed in physical sensor axes.
    [[nodiscard]] Vector3 get_acc_bias_body_at_temperature(T tempC) const {
        Vector3 b = get_acc_bias_at_temperature(tempC);
        if (std::abs(wind_heel_rad_) < T(1e-9)) return b;
        return Vector3(b.x(), cos_unheel_x_ * b.y() + sin_unheel_x_ * b.z(),
                       -sin_unheel_x_ * b.y() + cos_unheel_x_ * b.z());
    }

    void set_initial_acc_bias(const Vector3& b0) {
        if constexpr (with_accel_bias)
            xext.template segment<3>(OFF_BA) = b0;
    }

    // Set accelerometer bias temperature coefficient k_a  [m/s^2 per °C] per axis.
    // Model: b_a(tempC) = beta_a + k_a * (tempC - tempC_ref), with beta_a a slow OU residual
    void set_accel_bias_temp_coeff(const Vector3& ka_per_degC) { k_a_ = ka_per_degC; }

    /*
      Radius of the ball the accelerometer-bias estimate is confined to
      [m/s^2]. Set <= 0 to disable the projection.

      This is an implementation safety projection on the estimated
      accelerometer-bias state. The stability study treats it as the literal
      estimator operation it is: physical bias truth is not projected or
      reset, and post-correction projection is composed separately.

      The default is deliberately loose enough never to bind on a healthy
      MEMS unit (0.4 m/s^2 is about 41 mg, against tens of mg of turn-on bias
      plus temperature drift), so it acts as a guarantee rather than as a
      tuning parameter.
    */
    void set_accel_bias_limit(T limit_mps2) { acc_bias_limit_ = limit_mps2; }
    [[nodiscard]] T accel_bias_limit() const { return acc_bias_limit_; }

    void set_gyro_noise_density_rad_sqrt_s(const Vector3& density) {
        const Vector3 d = density.cwiseAbs();
        Qbase.template topLeftCorner<3,3>() = d.array().square().matrix().asDiagonal();
    }

    [[nodiscard]] static Vector3 gyro_noise_density_from_sample_std(
        const Vector3& sample_std_rad_s, T sample_period_s) {
        if (!(sample_period_s > T(0)) || !std::isfinite(sample_period_s)) return Vector3::Zero();
        return (sample_std_rad_s.cwiseAbs() * std::sqrt(sample_period_s)).eval();
    }

    // Toggle exact/structured Qd for the attitude+gyro-bias block.
    void set_exact_att_bias_Qd(bool on) { use_exact_att_bias_Qd_ = on; }

    // Initialize full extended state from "truth"
    void initialize_from_truth(const Vector3 &p_ned, const Vector3 &v_ned,
                               const Eigen::Quaternion<T> &q_bw, const Vector3 &a_w_ned);

	void set_param_rw_enabled(bool on) {
	    param_rw_enabled_ = on;
	    if (param_rw_enabled_) {
	        // Ensure matrices reflect filtered state immediately
	        refresh_model_params_from_filtered_();
	    }
	}

	// Optional tuning (log-domain stds)
	void set_param_rw_process_std_log(Vector3 sigma_acc_rw_log, Vector3 sigma_S_rw_log, T tau_rw_log) {
	    log_sigma_acc_f_.q = sigma_acc_rw_log.array().square().matrix();
	    log_sigma_S_f_.q   = sigma_S_rw_log.array().square().matrix();
	    log_tau_aw_f_.q    = tau_rw_log * tau_rw_log;
	}

	void set_param_cmd_std_log(Vector3 sigma_acc_cmd_log, Vector3 sigma_S_cmd_log, T tau_cmd_log) {
	    log_sigma_acc_f_.r = sigma_acc_cmd_log.array().square().matrix();
	    log_sigma_S_f_.r   = sigma_S_cmd_log.array().square().matrix();
	    log_tau_aw_f_.r    = tau_cmd_log * tau_cmd_log;
	}

	// Feed “commands” from your external adaptation
	void command_sigma_acc(const Vector3& sigma_acc_cmd) { param_rw_update_sigma_acc_cmd_(sigma_acc_cmd); }
	void command_sigma_S  (const Vector3& sigma_S_cmd)   { param_rw_update_sigma_S_cmd_(sigma_S_cmd); }
	void command_tau_aw   (T tau_cmd)                    { param_rw_update_tau_cmd_(tau_cmd); }

	// Convenience
	void apply_adaptive_params(const Vector3& sigma_acc_cmd, T tau_cmd, const Vector3& sigma_S_cmd) {
	    command_sigma_acc(sigma_acc_cmd);
	    command_tau_aw(tau_cmd);
	    command_sigma_S(sigma_S_cmd);
	}

    // IMU lever-arm API
    // r_b: IMU position w.r.t. CoG in the *physical* BODY frame B [m].
    // Internally we de-heel this into B' each step when applying lever-arm kinematics.
    void set_imu_lever_arm_body(const Vector3& r_b) {
        r_imu_wrt_cog_body_phys_ = r_b;
        use_imu_lever_arm_ = (r_b.squaredNorm() > T(0));
    }
    void clear_imu_lever_arm() {
        r_imu_wrt_cog_body_phys_.setZero();
        use_imu_lever_arm_ = false;
    }

    void set_alpha_smoothing_tau(T tau_sec) { alpha_smooth_tau_ = std::max(T(0), tau_sec); }

    // Set / update steady wind heel (roll about BODY X, rad).
    // Call this periodically (e.g. when your wind model changes) *before*
    // calling time_update/measurement_update_* for the next step.
	void update_wind_heel(T heel_rad) {
	    const T old = wind_heel_rad_;
	    if (heel_rad == old) return;

	    // Retarget internal B' frame FIRST (uses Δheel = new-old)
	    retarget_bodyprime_frame_(heel_rad - old);

	    // Now store new heel and update trig used by deheel_vector_()
	    wind_heel_rad_ = heel_rad;
	    update_unheel_trig_();
	}

    static Eigen::Matrix<T,3,1> ned_field_from_decl_incl(T D_rad, T I_rad, T B = T(1)) {
        const T cI = std::cos(I_rad), sI = std::sin(I_rad);
        const T cD = std::cos(D_rad), sD = std::sin(D_rad);
        return (Eigen::Matrix<T,3,1>() <<
            B * cI * cD,   // N
            B * cI * sD,   // E
            B * sI         // D (down positive)
        ).finished();
    }

  private:
    const T gravity_magnitude_ = T(STD_GRAVITY);

    // MEKF quaternion convention:
    //   - qref stores WORLD -> BODY' attitude, where BODY' is the virtual
    //     un-heeled body frame used internally by the filter.
    //   - quaternion() returns BODY' -> WORLD via qref.conjugate().
    //   - A world-frame reference vector v_world is predicted in BODY' as:
    //         v_bodyprime = R_wb() * v_world
    //
    // Important:
    //   v2ref is stored in WORLD coordinates (see initialize_from_acc_mag():
    //   v2ref = R_bw() * mag). Therefore the magnetometer prediction must be
    //   +R_wb() * v2ref. Flipping that sign here without also changing how
    //   v2ref is stored makes the innovation wrong even at the correct attitude.
    Eigen::Quaternion<T> qref;
    Vector3 v2ref = Vector3::UnitX();

    // Extended full state xext and Pext (NX x NX)
    Eigen::Matrix<T, NX, 1> xext; // [ δθ(3), (gyro bias 3 optional), v(3), p(3), S(3), a_w(3), (accel bias 3 optional) ]
    MatrixNX Pext;

    ocean_imu::kalman::filter_detail::GyroInterval<Vector3> gyro_interval_;
    Vector3 last_gyr_bias_corrected{};  // Last gyro

    T sigma_bacc0_ = T(0.004);          // initial accel bias std
    // Continuous driving-noise covariance of the residual accelerometer-bias
    // OU process: (5e-4)^2 (m/s^2)^2/s.  The driving standard deviation matches
    // acc_bias_rw in util/W3dSimCommon.h, applied there as sigma*sqrt(dt).
    // Bias and tilt can share low-frequency specific-force errors; this prior
    // does not by itself establish bias observability.
    Matrix3 Q_bacc_ = Matrix3::Identity() * T(2.5e-7);
    T tau_bacc_ = T(5000.0);             // residual accel-bias OU correlation time [s]

    // Accelerometer bias temperature coefficient (per-axis), units: m/s^2 per °C.
    // Default here reflects BMI270 typical accel drift (~0.002 m/s^2/°C).
    Vector3 k_a_ = Vector3::Constant(T(0.002));
    T acc_bias_limit_ = T(0.4);   // see set_accel_bias_limit()


    // Constant matrices
    Matrix3 Rmag;
    MatrixBaseN Qbase; // Q for attitude & bias

    Matrix3 Racc; // Accelerometer noise (diagonal) stored as Matrix3
    Matrix3 R_S;  // Triple integration measurement noise

    // World-acceleration OU process a_w dynamics parameters
    T tau_aw = T(2.1);            // correlation time [s], tune 1–3.5 s for sea states
    Matrix3 Sigma_aw_stat = Matrix3::Identity() * T(2.2*2.2); // stationary variance diag [ (m/s^2)^2 ]

    T pseudo_update_elapsed_s_ = T(0);
    T pseudo_update_period_s_ = T(0.015);

    bool acc_bias_updates_enabled_ = true;

    // false queues a PSD increment at prediction; true replaces the marginal
    // immediately without changing its cross-covariances.
    bool legacy_aw_covariance_replacement_ = false;
    bool aw_covariance_floor_pending_ = false;
    Matrix3 aw_covariance_floor_target_ = Matrix3::Zero();

    bool aw_process_correlated_ = false;
    bool use_exact_att_bias_Qd_ = true;

    // IMU lever-arm (off-CoG) support
    bool   use_imu_lever_arm_       = false;
    // Lever arm in *physical* BODY frame B (what you measure on the boat).
    Vector3 r_imu_wrt_cog_body_phys_ = Vector3::Zero();

    // Cached kinematics in the virtual un-heeled frame B'
    Vector3 prev_omega_b_ = Vector3::Zero(); // ω^{B'}
    Vector3 alpha_b_      = Vector3::Zero(); // α^{B'}
    bool    have_prev_omega_ = false;

    T last_dt_ = T(1.0/200);

    // Optional smoothing for alpha (0 = off)
    T alpha_smooth_tau_ = T(0.05); // seconds

    // Scratch buffers to avoid large stack allocation in time/measurement updates
    MatrixBaseN  F_AA_scratch_;
    MatrixBaseN  Q_AA_scratch_;

    Matrix12     F_LL_scratch_;
    Matrix12     Q_LL_scratch_;
    Matrix12     tmpLL_scratch_;

    Vector12     x_lin_prev_scratch_;
    Vector12     x_lin_next_scratch_;

    MatrixBaseN  tmpAA_scratch_;
    MatrixBaseN12 tmpAL_scratch_;

    MatrixNX3    PCt_scratch_;
    MatrixNX3    K_scratch_;
    Matrix3      S_scratch_;

    MeasDiag3 last_acc_diag_;
    MeasDiag3 last_mag_diag_;

    EIGEN_STRONG_INLINE void symmetrize_Pext_() {
        for (int i = 0; i < NX; ++i) {
            for (int j = i + 1; j < NX; ++j) {
                const T v = T(0.5) * (Pext(i,j) + Pext(j,i));
                Pext(i,j) = v;
                Pext(j,i) = v;
            }
        }
    }


    EIGEN_STRONG_INLINE void apply_pending_aw_covariance_inflation_() {
        if (!aw_covariance_floor_pending_) return;
        aw_covariance_floor_pending_ = false;

        Matrix3 P_aw = Pext.template block<3,3>(OFF_AW, OFF_AW);
        P_aw = T(0.5) * (P_aw + P_aw.transpose());
        Matrix3 Delta = aw_covariance_floor_target_ - P_aw;
        Delta = T(0.5) * (Delta + Delta.transpose());

        Eigen::SelfAdjointEigenSolver<Matrix3> es(Delta);
        if (es.info() != Eigen::Success) return;
        Vector3 evals = es.eigenvalues();
        for (int i = 0; i < 3; ++i) evals(i) = std::max(T(0), evals(i));
        Delta = es.eigenvectors() * evals.asDiagonal() * es.eigenvectors().transpose();
        Delta = T(0.5) * (Delta + Delta.transpose());

        Pext.template block<3,3>(OFF_AW, OFF_AW) += Delta;
    }

    // Closed-form helpers for rotation & integrals (constant ω over [0, t])

    // Rodrigues rotation and the integral
    //   B(t) = ∫_0^t exp(-[ω]× τ) dτ
    //
    // For this filter's left-multiplicative WORLD->BODY' attitude-error convention:
    //
    //   δθ̇ = -[ω]× δθ + δb_g + ...
    //
    // so the exact discrete cross-term is positive:
    //   Φ_{θb}(t) = +B(t)
    EIGEN_STRONG_INLINE void rot_and_B_from_wt_(const Vector3& w, T t, Matrix3& R, Matrix3& B) const {
        ocean_imu::kalman::ou_detail::rot_and_B_from_wt(w, t, R, B);
    }

    // ∫_0^T B(s) ds  (closed form; used for Q_{θb})
    EIGEN_STRONG_INLINE void integral_B_ds_(const Vector3& w, T step, Matrix3& IB) const {
        ocean_imu::kalman::ou_detail::integral_B_ds(w, step, IB);
    }

    // d/dω of (ω×(ω×r)) = (ω·r) I + ω rᵀ - 2 r ωᵀ
    EIGEN_STRONG_INLINE Matrix3 d_omega_x_omega_x_r_domega_(const Vector3& w, const Vector3& r) const {
        const T s = w.dot(r);
        return Matrix3::Identity() * s + (w * r.transpose()) - T(2) * (r * w.transpose());
    }

    // Simpson’s rule for ∫_0^T R(s) Q R(s)^T ds (fast, excellent for anisotropic Q)
    EIGEN_STRONG_INLINE Matrix3 simpson_R_Q_RT_(const Vector3& w, T step, const Matrix3& Q) const {
        return ocean_imu::kalman::ou_detail::simpson_R_Q_RT(w, step, Q);
    }

    // Simpson’s rule for ∫_0^T B(s) Q B(s)^T ds
    EIGEN_STRONG_INLINE Matrix3 simpson_B_Q_BT_(const Vector3& w, T step, const Matrix3& Q) const {
        return ocean_imu::kalman::ou_detail::simpson_B_Q_BT(w, step, Q);
    }

    EIGEN_STRONG_INLINE bool is_isotropic3_(const Matrix3& S, T tol = T(1e-9)) const {
        return ocean_imu::kalman::ou_detail::is_isotropic3(S, tol);
    }

    // convenience getters
    Matrix3 R_wb() const { return qref.toRotationMatrix(); }               // world→body'
    Matrix3 R_bw() const { return qref.toRotationMatrix().transpose(); }   // body'→world

    void set_accel_only_attitude_covariance_(
        T tilt_sigma_rad = T(0.035),   // about 2 deg
        T yaw_sigma_rad  = T(1.5708))  // about 90 deg, accel cannot observe yaw
    {
        const Vector3 world_down = Vector3::UnitZ();

        // qref is WORLD->BODY', so this is the world-down axis expressed in BODY'.
        Vector3 u_down_body = R_wb() * world_down;

        const T n = u_down_body.norm();
        if (!(n > T(1e-8)) || !u_down_body.allFinite()) {
            Pext.template block<3,3>(0,0) =
                Matrix3::Identity() * (yaw_sigma_rad * yaw_sigma_rad);
            return;
        }

        u_down_body /= n;

        const Matrix3 I = Matrix3::Identity();
        const Matrix3 P_yaw_axis  = u_down_body * u_down_body.transpose();
        const Matrix3 P_tilt_axes = I - P_yaw_axis;

        const T tilt_var = tilt_sigma_rad * tilt_sigma_rad;
        const T yaw_var  = yaw_sigma_rad  * yaw_sigma_rad;

        Matrix3 P_att = tilt_var * P_tilt_axes + yaw_var * P_yaw_axis;
        P_att = T(0.5) * (P_att + P_att.transpose());

        Pext.template block<3,3>(0,0) = P_att;
    }

    // Helpers
    // Every coupled correction and every prediction passes this guard.
    // It also precedes the invalid-attitude-injection early return.
    void project_gyro_bias_() {
        if constexpr (with_gyro_bias) {
            auto bias = xext.template segment<3>(3);
            ocean_imu::kalman::ou_detail::project_gyro_bias<T>(bias);
        }
    }

    Matrix3 skew_symmetric_matrix(const Eigen::Ref<const Vector3>& vec) const;
	Vector3 accelerometer_measurement_func(T tempC) const;

    static MatrixBaseN initialize_Q(Vector3 gyro_noise_density_rad_sqrt_s, T b0);

    // Quaternion & small-angle helpers (kept)
    void applyQuaternionCorrectionFromErrorState(); // apply correction to qref using xext(0..2)
    void project_acc_bias_();                       // confine b_a to a ball; see set_accel_bias_limit()
    void apply_error_state_reset_jacobian_(const Vector3& dtheta_injected);

    static void PhiAxis4x1_analytic(T tau, T h, Eigen::Matrix<T,4,4>& Phi_axis);
    static void QdAxis4x1_analytic(T tau, T h, T sigma2, Eigen::Matrix<T,4,4>& Qd_axis);

    // Reusable helpers for all 3×3 measurement updates

    // Factor S with LDLT and a diagonal safety boost if needed.
    // The `noise_scale` argument should be something like R.norm() or S.norm() from the branch.
    inline bool safe_ldlt3_(Matrix3& S, Eigen::LDLT<Matrix3>& ldlt, T noise_scale) const {
        ldlt.compute(S);
        if (ldlt.info() == Eigen::Success) return true;

        // Minimum positive bump
        const T bump = std::max(std::numeric_limits<T>::epsilon(), T(1e-6) * (noise_scale + T(1)));
        S.diagonal().array() += bump;

        ldlt.compute(S);
        return (ldlt.info() == Eigen::Success);
    }

    inline T nis3_from_ldlt_(const Eigen::LDLT<Matrix3>& ldlt,
                                          const Vector3& r) const
    {
        // Solve S x = r, nis = r^T x
        Vector3 x = ldlt.solve(r);
        if (!x.allFinite()) return std::numeric_limits<T>::quiet_NaN();
        const T v = r.dot(x);
        return std::isfinite(v) ? v : std::numeric_limits<T>::quiet_NaN();
    }

    // Compute K = PCt * S^-1 using vector solves instead of forming S^-1.
    // This keeps the ESP32/Arduino Eigen instantiation much smaller than
    // PCt * ldlt.solve(I), which can make cc1plus exhaust memory on Windows.
    inline void gain_from_ldlt3_(const Eigen::Matrix<T,NX,3>& PCt,
                                 const Eigen::LDLT<Matrix3>& ldlt,
                                 Eigen::Matrix<T,NX,3>& K) const
    {
        for (int i = 0; i < NX; ++i) {
            const Vector3 rhs(PCt(i,0), PCt(i,1), PCt(i,2));
            const Vector3 sol = ldlt.solve(rhs);
            K(i,0) = sol(0);
            K(i,1) = sol(1);
            K(i,2) = sol(2);
        }
    }

    // Joseph covariance update: P ← P - KCP - (KCP)ᵀ + K S Kᵀ.
    // Stack-light version: no NX×NX temporaries, only scalar loops.
    // Assumes Pext is symmetric on entry.
    inline void joseph_update3_(const Eigen::Matrix<T,NX,3>& K,
                                const Matrix3& S,
                                const Eigen::Matrix<T,NX,3>& PCt)
    {
        // We use that:
        //  • PCt = P Cᵀ  (N×3)
        //  • CP ≈ (PCt)ᵀ since P ≈ Pᵀ
        //
        // So:
        //   KCP(i,j) = Σ_l K(i,l) * CP(l,j) ≈ Σ_l K(i,l) * PCt(j,l)
        //   (KCP)ᵀ(j,i) = KCP(j,i)
        //
        // And K S Kᵀ is symmetric because S is symmetric.

        for (int i = 0; i < NX; ++i) {
            for (int j = i; j < NX; ++j) {

                // KCP_ij = (K C P)(i,j)
                T KCP_ij = T(0);
                T KCP_ji = T(0);
                for (int l = 0; l < 3; ++l) {
                    const T Ki_l = K(i,l);
                    const T Kj_l = K(j,l);
                    const T Pj_l = PCt(j,l); // CP(l,j) ≈ PCt(j,l)
                    const T Pi_l = PCt(i,l); // CP(l,i) ≈ PCt(i,l)

                    KCP_ij += Ki_l * Pj_l;
                    if (j != i) {
                        KCP_ji += Kj_l * Pi_l;
                    }
                }
                if (j == i) {
                    KCP_ji = KCP_ij;
                }

                // K S Kᵀ (i,j)
                T KSK_ij = T(0);
                for (int a = 0; a < 3; ++a) {
                    const T Kia = K(i,a);
                    for (int b = 0; b < 3; ++b) {
                        const T Kjb = K(j,b);
                        KSK_ij += Kia * S(a,b) * Kjb;
                    }
                }
                const T delta = - (KCP_ij + KCP_ji) + KSK_ij;

                // Apply symmetric update
                Pext(i,j) += delta;
                if (j != i) {
                    Pext(j,i) = Pext(i,j);
                }
            }
        }
        // Final symmetry clean-up (cheap but good hygiene)
        symmetrize_Pext_();
    }

    void zero_AL_cross_cov_once_() {
        constexpr int NA = BASE_N;
        constexpr int NL = 12; // [v,p,S,a_w]
        Pext.template block<NA,NL>(0, OFF_V).setZero();
        Pext.template block<NL,NA>(OFF_V, 0).setZero();
    }

    EIGEN_STRONG_INLINE void freeze_acc_bias_rows_(MatrixNX3& M) const {
        if constexpr (with_accel_bias) {
            M.template block<3,3>(OFF_BA, 0).setZero();
        }
    }

    // Steady wind heel model (roll about BODY X)
    // wind_heel_rad_ : current steady heel in radians (hull frame)
    // Internally we work in a virtual "un-heeled" body frame B'
    // with rotation R_x(-wind_heel_rad_). We cache cos/sin for speed.
    T wind_heel_rad_  = T(0);
    T cos_unheel_x_   = T(1);  // cos(-wind_heel)
    T sin_unheel_x_   = T(0);  // sin(-wind_heel)

    EIGEN_STRONG_INLINE void update_unheel_trig_() {
        if (std::abs(wind_heel_rad_) < T(1e-9)) {
            cos_unheel_x_ = T(1);
            sin_unheel_x_ = T(0);
        } else {
            const T angle = -wind_heel_rad_;
            cos_unheel_x_ = std::cos(angle);
            sin_unheel_x_ = std::sin(angle);
        }
    }

    // Rotate a BODY-frame vector into the virtual un-heeled frame B'
    EIGEN_STRONG_INLINE Vector3 deheel_vector_(const Vector3& v_body) const {
        // R_x(-heel) * v
        if (std::abs(wind_heel_rad_) < T(1e-9)) {
            return v_body;
        }
        Vector3 v;
        v.x() = v_body.x();
        v.y() = cos_unheel_x_ * v_body.y() - sin_unheel_x_ * v_body.z();
        v.z() = sin_unheel_x_ * v_body.y() + cos_unheel_x_ * v_body.z();
        return v;
    }

	EIGEN_STRONG_INLINE Matrix3 Rx_(T angle_rad) const {
	    const T c = std::cos(angle_rad);
	    const T s = std::sin(angle_rad);
	    Matrix3 R;
	    R << T(1), T(0), T(0),
	         T(0),    c,   -s,
	         T(0),    s,    c;
	    return R;
	}

	// Retarget internal B' frame after heel changes.
	// Keeps the *physical* attitude and bias meaning continuous.
	void retarget_bodyprime_frame_(T delta_heel_rad)
	{
	    if (std::abs(delta_heel_rad) < T(1e-12)) return;

	    // R = Rx(-Δheel): maps old B' coordinates -> new B' coordinates.
	    const Matrix3 R = Rx_(-delta_heel_rad);

	    // Rotate the attitude reference: R_wb' := R * R_wb'
	    // qref is world->B'. Left-multiply by the frame change.
	    const Eigen::Quaternion<T> qR(R);
	    qref = qR * qref;
	    qref.normalize();

	    // Rotate any vector states that live in B' coordinates
	    xext.template segment<3>(0) = R * xext.template segment<3>(0); // δθ (error state)

	    if constexpr (with_gyro_bias) {
	        xext.template segment<3>(3) = R * xext.template segment<3>(3); // b_g
	        project_gyro_bias_();
	    }
	    if constexpr (with_accel_bias) {
	        xext.template segment<3>(OFF_BA) = R * xext.template segment<3>(OFF_BA); // b_a (as stored)
	    }

	    // Rotate cached B' kinematics
	    last_gyr_bias_corrected = R * last_gyr_bias_corrected;
	    prev_omega_b_           = R * prev_omega_b_;
	    alpha_b_                = R * alpha_b_;

	    // Similarity-transform covariance for the rotated state blocks.
	    // Since NX is small (~18), do the safe full similarity update (only on heel change).
	    MatrixNX Tm = MatrixNX::Identity();
	    Tm.template block<3,3>(0,0) = R;
	    if constexpr (with_gyro_bias)  Tm.template block<3,3>(3,3)      = R;
	    if constexpr (with_accel_bias) Tm.template block<3,3>(OFF_BA,OFF_BA) = R;

	    Pext = Tm * Pext * Tm.transpose();
	    symmetrize_Pext_();

	    // Optional: α cache is now in new B' but it was computed using old dt history.
	    // have_prev_omega_ = false; alpha_b_.setZero();
	}

	// Commanded-parameter RW filter (log-domain)
	struct RWScalar {
	    T x = T(0);    // mean
	    T P = T(1e-6); // variance
	    T q = T(0);    // process var per second (RW)
	    T r = T(0);    // measurement var (command)

	    void predict(T dt) {
	        if (dt > T(0)) P += q * dt;
	        if (!(P > T(0)) || !std::isfinite(P)) P = T(1e-6);
	    }
	    void update(T z) {
	        const T S = P + r;
	        if (!(S > T(0)) || !std::isfinite(S)) return;
	        const T K = P / S;
	        x = x + K * (z - x);
	        P = (T(1) - K) * P;
	        if (!(P > T(0)) || !std::isfinite(P)) P = T(1e-9);
	    }
	};

	struct RWVec3Diag {
	    Vector3 x = Vector3::Zero();          // mean (per axis)
	    Vector3 P = Vector3::Constant(T(1e-6));
	    Vector3 q = Vector3::Zero();          // process var per second
	    Vector3 r = Vector3::Zero();          // meas var

	    void predict(T dt) {
	        if (dt > T(0)) P.array() += q.array() * dt;
	        for (int i = 0; i < 3; ++i) {
	            if (!(P(i) > T(0)) || !std::isfinite(P(i))) P(i) = T(1e-6);
	        }
	    }
	    void update(const Vector3& z) {
	        for (int i = 0; i < 3; ++i) {
	            const T S = P(i) + r(i);
	            if (!(S > T(0)) || !std::isfinite(S)) continue;
	            const T K = P(i) / S;
	            x(i) = x(i) + K * (z(i) - x(i));
	            P(i) = (T(1) - K) * P(i);
	            if (!(P(i) > T(0)) || !std::isfinite(P(i))) P(i) = T(1e-9);
	        }
	    }
	};

	static inline T clamp_pos_(T v, T lo, T hi) {
	    if (!std::isfinite(v)) return lo;
	    return std::max(lo, std::min(v, hi));
	}

	static inline Vector3 clamp_pos_vec_(const Vector3& v, T lo, T hi) {
	    Vector3 out = v;
	    out.x() = clamp_pos_(out.x(), lo, hi);
	    out.y() = clamp_pos_(out.y(), lo, hi);
	    out.z() = clamp_pos_(out.z(), lo, hi);
	    return out;
	}

	// Enable/disable commanded-parameter filtering
	bool param_rw_enabled_ = false;

	// Log-parameters we filter:
	//  - log(sigma_acc)  -> used to build Racc
	//  - log(sigma_S)    -> used to build R_S (diag)
	//  - log(tau_aw)     -> used for OU time constant
	RWVec3Diag log_sigma_acc_f_;
	RWVec3Diag log_sigma_S_f_;
	RWScalar   log_tau_aw_f_;

	// Safety clamps (physical units)
	T sigma_acc_min_ = T(1e-4), sigma_acc_max_ = T(50);   // m/s^2
	T sigma_S_min_   = T(1e-6), sigma_S_max_   = T(1e6);  // m*s (depends on your S meaning)
	T tau_min_       = T(1e-3), tau_max_       = T(60);   // s

	EIGEN_STRONG_INLINE void refresh_model_params_from_filtered_() {
	    // sigma_acc
	    Vector3 sigma_acc = log_sigma_acc_f_.x.array().exp().matrix();
	    sigma_acc = clamp_pos_vec_(sigma_acc, sigma_acc_min_, sigma_acc_max_);
	    Racc = sigma_acc.array().square().matrix().asDiagonal();

	    // sigma_S -> R_S (diag)
	    Vector3 sigma_S = log_sigma_S_f_.x.array().exp().matrix();
	    sigma_S = clamp_pos_vec_(sigma_S, sigma_S_min_, sigma_S_max_);
	    R_S = sigma_S.array().square().matrix().asDiagonal();
	    R_S = T(0.5) * (R_S + R_S.transpose());

	    // tau_aw
	    T tau = std::exp(log_tau_aw_f_.x);
	    tau = clamp_pos_(tau, tau_min_, tau_max_);
	    tau_aw = tau;
	}

	EIGEN_STRONG_INLINE void param_rw_predict_(T dt) {
	    if (!param_rw_enabled_) return;
	    log_sigma_acc_f_.predict(dt);
	    log_sigma_S_f_.predict(dt);
	    log_tau_aw_f_.predict(dt);
	    refresh_model_params_from_filtered_();
	}

	EIGEN_STRONG_INLINE void param_rw_update_sigma_acc_cmd_(const Vector3& sigma_acc_cmd) {
	    if (!param_rw_enabled_) {
	        set_Racc_std(sigma_acc_cmd);
	        return;
	    }
	    Vector3 s = clamp_pos_vec_(sigma_acc_cmd, sigma_acc_min_, sigma_acc_max_);
	    Vector3 z = s.array().log().matrix();
	    log_sigma_acc_f_.update(z);
	    refresh_model_params_from_filtered_();
	}

	EIGEN_STRONG_INLINE void param_rw_update_sigma_S_cmd_(const Vector3& sigma_S_cmd) {
	    if (!param_rw_enabled_) {
	        set_RS_noise(sigma_S_cmd);
	        return;
	    }
	    Vector3 s = clamp_pos_vec_(sigma_S_cmd, sigma_S_min_, sigma_S_max_);
	    Vector3 z = s.array().log().matrix();
	    log_sigma_S_f_.update(z);
	    refresh_model_params_from_filtered_();
	}

	EIGEN_STRONG_INLINE void param_rw_update_tau_cmd_(T tau_cmd) {
	    if (!param_rw_enabled_) {
	        set_aw_time_constant(tau_cmd);
	        return;
	    }
	    const T t = clamp_pos_(tau_cmd, tau_min_, tau_max_);
	    const T z = std::log(t);
	    log_tau_aw_f_.update(z);
	    refresh_model_params_from_filtered_();
	}
};

// Implementation

template <typename T, bool with_gyro_bias, bool with_accel_bias>
Kalman3D_Wave_OU_III<T, with_gyro_bias, with_accel_bias>::Kalman3D_Wave_OU_III(
    Vector3 const& sigma_a,
    Vector3 const& gyro_noise_density_rad_sqrt_s,
    Vector3 const& sigma_m,
    T Pq0, T Pb0, T b0, T R_S_noise_var, T gravity_magnitude)
  : gravity_magnitude_(gravity_magnitude),
    Rmag(sigma_m.array().square().matrix().asDiagonal()),
    Qbase(initialize_Q(gyro_noise_density_rad_sqrt_s, b0)),
    Racc(sigma_a.array().square().matrix().asDiagonal())
{
    qref.setIdentity();  // quaternion init

    R_S = Matrix3::Identity() * R_S_noise_var;

    // initialize base / extended states
    MatrixBaseN Pbase;
    Pbase.setIdentity(); // default small initial cov unless user overwrites

    // initialize base covariance
    Pbase.template topLeftCorner<3,3>() = Matrix3::Identity() * Pq0;   // attitude error covariance
    if constexpr (with_gyro_bias) {
        Pbase.template block<3,3>(3,3) = Matrix3::Identity() * Pb0;    // bias covariance
    }

    // Extended state
    xext.setZero();
    Pext.setZero();

    // Place base P into top-left of Pext
    Pext.topLeftCorner(BASE_N, BASE_N) = Pbase;

    // Seed covariance for a_w (world acceleration)
    Pext.template block<3,3>(OFF_AW, OFF_AW) = Sigma_aw_stat;

    if constexpr (with_accel_bias) {
        Pext.template block<3,3>(OFF_BA, OFF_BA) = Matrix3::Identity() * sigma_bacc0_ * sigma_bacc0_;
    }

    const T sigma_v0 = T(1.0);    // m/s
    const T sigma_p0 = T(20.0);   // m
    const T sigma_S0 = T(50.0);   // m·s
    set_initial_linear_uncertainty(sigma_v0, sigma_p0, sigma_S0);

	// Init commanded-parameter filter means from current settings
	{
	    // Racc was built from sigma_a input
	    Vector3 sigma_acc0;
	    sigma_acc0.x() = std::sqrt(std::max(T(0), Racc(0,0)));
	    sigma_acc0.y() = std::sqrt(std::max(T(0), Racc(1,1)));
	    sigma_acc0.z() = std::sqrt(std::max(T(0), Racc(2,2)));

	    // R_S in your ctor is "variance" scalar; convert to std
	    const T sigma_S_noise_std = std::sqrt(std::max(T(1e-12), R_S_noise_var));
	    Vector3 sigma_S0v = Vector3::Constant(sigma_S_noise_std);

	    log_sigma_acc_f_.x = clamp_pos_vec_(sigma_acc0, sigma_acc_min_, sigma_acc_max_).array().log().matrix();
	    log_sigma_S_f_.x   = clamp_pos_vec_(sigma_S0v,  sigma_S_min_,   sigma_S_max_  ).array().log().matrix();
	    log_tau_aw_f_.x    = std::log(clamp_pos_(tau_aw, tau_min_, tau_max_));

	    // Reasonable default uncertainties (in log-domain)
	    log_sigma_acc_f_.P = Vector3::Constant(T(0.10) * T(0.10)); // ~10% 1σ
	    log_sigma_S_f_.P   = Vector3::Constant(T(0.15) * T(0.15)); // ~15% 1σ
	    log_tau_aw_f_.P    = T(0.20) * T(0.20);                    // ~20% 1σ

	    // Default RW diffusion (log units per sqrt(s)) -> variance per second
	    const T rw_sig_acc = T(0.02); // ~2%/sqrt(s)
	    const T rw_sig_S   = T(0.02);
	    const T rw_tau     = T(0.01);

	    log_sigma_acc_f_.q = Vector3::Constant(rw_sig_acc * rw_sig_acc);
	    log_sigma_S_f_.q   = Vector3::Constant(rw_sig_S   * rw_sig_S);
	    log_tau_aw_f_.q    = rw_tau * rw_tau;

	    // Default command noise (how noisy the external adapter is), log-domain
	    const T cmd_sig_acc = T(0.10); // ~10%
	    const T cmd_sig_S   = T(0.15); // ~15%
	    const T cmd_tau     = T(0.20); // ~20%

	    log_sigma_acc_f_.r = Vector3::Constant(cmd_sig_acc * cmd_sig_acc);
	    log_sigma_S_f_.r   = Vector3::Constant(cmd_sig_S   * cmd_sig_S);
	    log_tau_aw_f_.r    = cmd_tau * cmd_tau;
	}
}

template<typename T, bool with_gyro_bias, bool with_accel_bias>
typename Kalman3D_Wave_OU_III<T, with_gyro_bias, with_accel_bias>::MatrixBaseN
Kalman3D_Wave_OU_III<T, with_gyro_bias, with_accel_bias>::initialize_Q(
              typename Kalman3D_Wave_OU_III<T, with_gyro_bias, with_accel_bias>::Vector3 gyro_noise_density_rad_sqrt_s, T b0) {
    MatrixBaseN Q; Q.setZero();
    if constexpr (with_gyro_bias) {
        Q.template topLeftCorner<3,3>() = gyro_noise_density_rad_sqrt_s.array().square().matrix().asDiagonal(); // gyro RW
        Q.template bottomRightCorner<3,3>() = Matrix3::Identity() * b0;                   // bias RW
    } else {
        Q = gyro_noise_density_rad_sqrt_s.array().square().matrix().asDiagonal();
    }
    return Q;
}

template <typename T, bool with_gyro_bias, bool with_accel_bias>
void Kalman3D_Wave_OU_III<T, with_gyro_bias, with_accel_bias>::set_aw_stationary_cov_full(const Matrix3& Sigma_in)
{
    Matrix3 S = T(0.5) * (Sigma_in + Sigma_in.transpose());
    ocean_imu::kalman::ou_detail::regularize_psd_if_needed<T,3>(S);
    Sigma_aw_stat = S;

    Matrix3 off = S;
    off.diagonal().setZero();
    const T scale = std::max(T(1), S.cwiseAbs().maxCoeff());
    aw_process_correlated_ = off.cwiseAbs().maxCoeff()
        > T(64) * std::numeric_limits<T>::epsilon() * scale;
}

// Initialization from accelerometer + magnetometer
// Inputs:
//   acc_body  — accelerometer specific force in body frame (NED)
//   mag_body  — magnetometer measurement in body frame (NED)
template<typename T, bool with_gyro_bias, bool with_accel_bias>
bool Kalman3D_Wave_OU_III<T, with_gyro_bias, with_accel_bias>::initialize_from_acc_mag(
    Vector3 const& acc_body,
    Vector3 const& mag_body)
{
    const Vector3 acc = deheel_vector_(acc_body);
    const Vector3 mag = deheel_vector_(mag_body);
    if (!acc.allFinite() || !mag.allFinite()) {
        return false;
    }

    // use acc & mag as if they are BODY-frame (interpreted as B').
    // Normalize accelerometer
    const T anorm = acc.norm();
    if (!(anorm >= T(1e-8))) {
        return false;
    }

    const T mnorm = mag.norm();
    if (!(mnorm >= T(1e-8))) {
        return false;
    }

    const Vector3 acc_n = acc / anorm;

    // WORLD axes expressed in BODY' coordinates
    const Vector3 z_world = -acc_n;  // world down axis in body coords

    Vector3 mag_h = mag - (mag.dot(z_world)) * z_world;
    const T mh = mag_h.norm();
    if (!(mh >= T(1e-8))) {
        return false;
    }
    mag_h /= mh;
    project_gyro_bias_();  // only once the input is accepted

    const Vector3 x_world = mag_h;                    // magnetic north in body coords
    const Vector3 y_world = z_world.cross(x_world).normalized();

    Matrix3 R_wb_new;
    R_wb_new.col(0) = x_world;
    R_wb_new.col(1) = y_world;
    R_wb_new.col(2) = z_world;

    qref = Eigen::Quaternion<T>(R_wb_new);
    qref.normalize();

    // Store world magnetic reference consistent with the new attitude.
    v2ref = R_bw() * mag;

    // This is an external hard attitude reset. Make EKF state/covariance coherent.
    xext.template head<3>().setZero();

    // Re-seed attitude covariance.
    Pext.template block<3,3>(0,0) = Matrix3::Identity() * T(5e-4);

    // Old attitude cross-covariances are now stale.
    if constexpr (with_gyro_bias) {
        Pext.template block<3,3>(0,3).setZero();
        Pext.template block<3,3>(3,0).setZero();

        // Give mag some room to re-tie yaw to gyro bias after relock.
        auto Pbg = Pext.template block<3,3>(3,3);
        const T bg_var_floor = T(1e-6);
        for (int i = 0; i < 3; ++i) {
            Pbg(i,i) = std::max(Pbg(i,i), bg_var_floor);
        }
        Pext.template block<3,3>(3,3) = Pbg;
    }

    // Zero attitude <-> linear cross-covariances.
    zero_AL_cross_cov_once_();

    if constexpr (with_accel_bias) {
        Pext.template block<3,3>(0, OFF_BA).setZero();
        Pext.template block<3,3>(OFF_BA, 0).setZero();
    }

    symmetrize_Pext_();
    return true;
}

template<typename T, bool with_gyro_bias, bool with_accel_bias>
Eigen::Quaternion<T>
Kalman3D_Wave_OU_III<T, with_gyro_bias, with_accel_bias>::quaternion_from_acc(Vector3 const& acc)
{
    // Raw accelerometer is specific force; at rest in NED: acc ≈ (0,0,-g) in body
    // We want body +Z (down) to align with world +Z (down), i.e. align zb to -acc.
    Vector3 an = acc.normalized();
    Vector3 zb = Vector3::UnitZ();

    // Rotate zb to -an
    Vector3 target = -an;
    T cos_theta = zb.dot(target);
    Vector3 axis = zb.cross(target);
    T norm_axis = axis.norm();

    if (norm_axis < T(1e-8)) {
        // Almost parallel or anti-parallel
        if (cos_theta > 0) {
            return Eigen::Quaternion<T>::Identity();        // zb ≈ target
        } else {
            return Eigen::Quaternion<T>(0, 1, 0, 0);        // 180° about X
        }
    }

    axis /= norm_axis;
    // clamp to avoid NaNs
    cos_theta = std::max(T(-1), std::min(T(1), cos_theta));
    T angle = std::acos(cos_theta);

    Eigen::AngleAxis<T> aa(angle, axis);
    Eigen::Quaternion<T> q(aa);
    q.normalize();
    return q;
}

template<typename T, bool with_gyro_bias, bool with_accel_bias>
bool Kalman3D_Wave_OU_III<T, with_gyro_bias, with_accel_bias>::initialize_from_acc(Vector3 const& acc_body)
{
    const Vector3 acc = deheel_vector_(acc_body);

    const T anorm = acc.norm();
    if (!acc.allFinite() || !(anorm >= T(1e-8))) {
       return false;
    }
    const Vector3 acc_n = acc / anorm;
    project_gyro_bias_();  // only once the input is accepted

    // Use accelerometer to align z axis, yaw remains arbitrary
    qref = quaternion_from_acc(acc_n);
    qref.normalize();

    xext.template head<3>().setZero();

    // Accel-only initialization observes gravity direction only.
    // It constrains tilt but leaves yaw around world-down unobservable.
    set_accel_only_attitude_covariance_();

    if constexpr (with_gyro_bias) {
        Pext.template block<3,3>(0,3).setZero();
        Pext.template block<3,3>(3,0).setZero();
    }

    zero_AL_cross_cov_once_();

    if constexpr (with_accel_bias) {
        Pext.template block<3,3>(0, OFF_BA).setZero();
        Pext.template block<3,3>(OFF_BA, 0).setZero();
    }

    symmetrize_Pext_();
    return true;
}

// Seed the filter from an attitude solved outside it.
//
// This is initialize_from_acc() with the gravity direction replaced by a
// supplied quaternion and the yaw variance made an argument.  Both differences
// matter to the caller it exists for.  An accelerometer sample is gravity plus
// the orbital specific force, so tilt rebuilt from one instant carries a
// wave-correlated error, while an external observer that has been integrating
// gyro through the wave band does not; and once a magnetometer has gauged the
// heading, yaw is no longer the unobservable direction that
// set_accel_only_attitude_covariance_() assumes by default.
//
// Everything else is deliberately identical: the attitude error state is
// zeroed, the covariance is rebuilt as an anisotropic tilt/yaw split about the
// world-down axis, and the attitude-to-bias cross-covariances are dropped,
// since a correlation learned against the discarded attitude does not describe
// the new one.
template<typename T, bool with_gyro_bias, bool with_accel_bias>
bool Kalman3D_Wave_OU_III<T, with_gyro_bias, with_accel_bias>::initialize_from_attitude(
    Eigen::Quaternion<T> const& q_bw,
    T tilt_sigma_rad,
    T yaw_sigma_rad)
{
    if (!q_bw.coeffs().allFinite()) {
        return false;
    }
    if (!(q_bw.norm() > T(1e-8))) {
        return false;
    }

    // Writes qref through the un-heel composition and zeroes the attitude
    // error state, which is exactly the head<3>() reset initialize_from_acc()
    // performs by hand.
    set_quaternion_boat(q_bw);

    const T tilt_sigma = (std::isfinite(tilt_sigma_rad) && tilt_sigma_rad > T(0))
                             ? tilt_sigma_rad
                             : T(0.035);
    const T yaw_sigma = (std::isfinite(yaw_sigma_rad) && yaw_sigma_rad > T(0))
                            ? yaw_sigma_rad
                            : T(1.5708);

    set_accel_only_attitude_covariance_(tilt_sigma, yaw_sigma);

    if constexpr (with_gyro_bias) {
        Pext.template block<3,3>(0,3).setZero();
        Pext.template block<3,3>(3,0).setZero();
    }

    zero_AL_cross_cov_once_();

    if constexpr (with_accel_bias) {
        Pext.template block<3,3>(0, OFF_BA).setZero();
        Pext.template block<3,3>(OFF_BA, 0).setZero();
    }

    symmetrize_Pext_();
    return true;
}

template<typename T, bool with_gyro_bias, bool with_accel_bias>
bool Kalman3D_Wave_OU_III<T, with_gyro_bias, with_accel_bias>::initialize_from_acc_preserve_yaw(
    Vector3 const& acc_body)
{
    const Eigen::Quaternion<T> q_old_bw = quaternion_boat();
    if (!std::isfinite(q_old_bw.x()) || !std::isfinite(q_old_bw.y()) ||
        !std::isfinite(q_old_bw.z()) || !std::isfinite(q_old_bw.w()))
    {
        return initialize_from_acc(acc_body);
    }

    const T ox = q_old_bw.x();
    const T oy = q_old_bw.y();
    const T oz = q_old_bw.z();
    const T ow = q_old_bw.w();
    const T siny_cosp = T(2) * (ow * oz + ox * oy);
    const T cosy_cosp = T(1) - T(2) * (oy * oy + oz * oz);
    const T yaw_old = std::atan2(siny_cosp, cosy_cosp);

    // Re-lock tilt from accelerometer first.
    if (!initialize_from_acc(acc_body)) return false;

    Eigen::Quaternion<T> q_tilt_bw = quaternion_boat();
    const T nq_tilt = q_tilt_bw.norm();
    if (!(nq_tilt > T(1e-8))) return true;
    q_tilt_bw.normalize();

    const T tx = q_tilt_bw.x();
    const T ty = q_tilt_bw.y();
    const T tz = q_tilt_bw.z();
    const T tw = q_tilt_bw.w();

    const T sinp_raw = T(2) * (tw * ty - tz * tx);
    const T sinp = std::max(T(-1), std::min(T(1), sinp_raw));
    const T pitch = std::asin(sinp);

    const T sinr_cosp = T(2) * (tw * tx + ty * tz);
    const T cosr_cosp = T(1) - T(2) * (tx * tx + ty * ty);
    const T roll = std::atan2(sinr_cosp, cosr_cosp);

    const Eigen::Quaternion<T> q_yaw(Eigen::AngleAxis<T>(yaw_old, Vector3::UnitZ()));
    const Eigen::Quaternion<T> q_pitch(Eigen::AngleAxis<T>(pitch, Vector3::UnitY()));
    const Eigen::Quaternion<T> q_roll(Eigen::AngleAxis<T>(roll, Vector3::UnitX()));

    Eigen::Quaternion<T> q_new_bw = q_yaw * q_pitch * q_roll;
    q_new_bw.normalize();
    set_quaternion_boat(q_new_bw);
    return true;
}

template <typename T, bool with_gyro_bias, bool with_accel_bias>
void Kalman3D_Wave_OU_III<T, with_gyro_bias, with_accel_bias>::initialize_from_truth(
    const Vector3 &p_ned, const Vector3 &v_ned,
    const Eigen::Quaternion<T> &q_bw, const Vector3 &a_w_ned)
{
    // Reset entire error state to 0
    xext.setZero();

    // Load linear states directly from truth
    xext.template segment<3>(OFF_V)  = v_ned;    // velocity (world NED)
    xext.template segment<3>(OFF_P)  = p_ned;    // position (world NED)
    xext.template segment<3>(OFF_S).setZero();   // integral of p, start at 0
    xext.template segment<3>(OFF_AW) = a_w_ned;  // world acceleration (OU state)

    // Bias states = 0
    if constexpr (with_gyro_bias) {
        xext.template segment<3>(3).setZero();       // gyro bias block
    }
    if constexpr (with_accel_bias) {
        xext.template segment<3>(OFF_BA).setZero();  // accel bias block
    }

    // Input q_bw is the PHYSICAL boat/body attitude B->W.
    // Internally we store qref = W->B', where B' is the virtual un-heeled body frame.
    //
    // q_B'B : B -> B'  ("un-heel" rotation)
    // q_BB' : B' -> B
    // q_WB' = q_BW * q_BB'
    Eigen::Quaternion<T> q_in = q_bw;
    const T nq = q_in.norm();
    if (!(nq > T(1e-8))) {
        qref.setIdentity();
    } else {
        q_in.normalize();

        const T half = -wind_heel_rad_ * T(0.5);
        const T c = std::cos(half);
        const T s = std::sin(half);

        const Eigen::Quaternion<T> q_BprimeB(c, s, 0, 0);   // B -> B'
        const Eigen::Quaternion<T> q_BBprime = q_BprimeB.conjugate(); // B' -> B

        const Eigen::Quaternion<T> q_WBprime = q_in * q_BBprime; // B' -> W
        qref = q_WBprime.conjugate();                            // W -> B'
        qref.normalize();
    }

    // Reset covariance
    Pext.setZero();
    const T p_0 = T(1e-5);
    Pext.diagonal().array() = p_0;

    // Keep cached kinematics coherent with the fresh reset
    last_gyr_bias_corrected.setZero();
    prev_omega_b_.setZero();
    alpha_b_.setZero();
    have_prev_omega_ = false;
}

template<typename T, bool with_gyro_bias, bool with_accel_bias>
void Kalman3D_Wave_OU_III<T, with_gyro_bias, with_accel_bias>::time_update(
    Vector3 const& gyr_body, T Ts)
{
    if (!(Ts > T(0)) || !std::isfinite(Ts) || !gyr_body.allFinite()) return;
    const auto interval = gyro_interval_.prepare(gyr_body, Ts);
    if (!interval.predict) return;
    project_gyro_bias_();
    last_dt_ = Ts;   // Remember last dt

	// Commanded parameters random-walk prediction (updates Racc, R_S, tau_aw smoothly)
	param_rw_predict_(Ts);

    // De-heel gyro into virtual frame B' using current wind_heel_rad_
    const Vector3 gyr = deheel_vector_(interval.rate);   // ω^{B'}

    // Attitude propagation
    Vector3 gyro_bias;
    if constexpr (with_gyro_bias) {
        gyro_bias = xext.template segment<3>(3);
    } else {
        gyro_bias = Vector3::Zero();
    }
    last_gyr_bias_corrected = gyr - gyro_bias;

    // IMU lever-arm: estimate angular acceleration α^{B'} (from bias-corrected ω^{B'})
    const Vector3 omega_b = deheel_vector_(gyr_body) - gyro_bias;
    if (have_prev_omega_ && Ts > T(0)) {
        const Vector3 alpha_raw = (omega_b - prev_omega_b_) / Ts;
        if (alpha_smooth_tau_ > T(0)) {
            const T a = T(1) - std::exp(-Ts / alpha_smooth_tau_);
            alpha_b_ = (T(1) - a) * alpha_b_ + a * alpha_raw;
        } else {
            alpha_b_ = alpha_raw;
        }
    } else {
        alpha_b_.setZero();
        have_prev_omega_ = true;
    }
    prev_omega_b_ = omega_b;

    // qref stores WORLD->BODY'.
    // With body-frame angular rate omega^{B'}, propagate as:
    //   q_wb(k+1) = dq(-omega*dt) * q_wb(k)
    const Eigen::Quaternion<T> dq_wb = ocean_imu::kalman::ou_detail::quat_from_delta_theta((-last_gyr_bias_corrected * Ts).eval());
    qref = dq_wb * qref;
    qref.normalize();

    // Attitude block F_AA, Q_AA
    Matrix3 I = Matrix3::Identity();
    const Vector3 w = last_gyr_bias_corrected;
    const T omega = w.norm();
    const T theta = omega * Ts;

    MatrixBaseN& F_AA = F_AA_scratch_;
    F_AA.setIdentity();

    if (theta < T(1e-5)) {
        Matrix3 Wx = skew_symmetric_matrix(w);
        F_AA.template topLeftCorner<3,3>() = I - Wx*Ts + (Wx*Wx)*(Ts*Ts/T(2));
    } else {
        Matrix3 W = skew_symmetric_matrix(w / (omega + std::numeric_limits<T>::epsilon()));
        const T s = std::sin(theta), c = std::cos(theta);
        F_AA.template topLeftCorner<3,3>() = I - s*W + (T(1)-c)*(W*W);
    }
    if constexpr (with_gyro_bias) {
		Matrix3 Rstep, Bstep;
		rot_and_B_from_wt_(w, Ts, Rstep, Bstep);

		// exact discrete attitude error transition
		F_AA.template topLeftCorner<3,3>() = Rstep;

        // Left-multiplicative WORLD->BODY' attitude error:
        //   δθ̇ = -[ω]× δθ + δb_g + ...
        // Hence the exact discrete cross-term is
        //   Φ_{θb} = +∫_0^Ts exp(-[ω]× s) ds
        // whose small-angle limit is
        //   +I*Ts - 1/2 [ω]× Ts² + ...
		F_AA.template block<3,3>(0,3) = Bstep;
    }

    MatrixBaseN& Q_AA = Q_AA_scratch_;
    Q_AA.setZero();

    if (!use_exact_att_bias_Qd_) {
        // fast path
        Q_AA = Qbase * Ts;
        Q_AA.template topLeftCorner<3,3>() *= interval.noise_scale;
    } else {
        // Structured/closed-form path for [δθ, b_g] with constant ω over the step
        const Matrix3 Qg  = Qbase.template topLeftCorner<3,3>() * interval.noise_scale;
        [[maybe_unused]] Matrix3 Qbg; Qbg.setZero();
        if constexpr (with_gyro_bias) {
            Qbg = Qbase.template bottomRightCorner<3,3>();
        }

        // ∫ R(s) Qg R(s)^T ds  (exact if isotropic; Simpson for anisotropic)
        Matrix3 I_R;
        if (is_isotropic3_(Qg)) {
            I_R = Matrix3::Identity() * (Qg(0,0) * Ts);     // exact
        } else {
            I_R = simpson_R_Q_RT_(w, Ts, Qg);               // very accurate, still cheap
        }

        // ∫ B(s) Qbg B(s)^T ds  (Simpson)
        Matrix3 I_BB = Matrix3::Zero();
        if constexpr (with_gyro_bias) {
            I_BB = simpson_B_Q_BT_(w, Ts, Qbg);
        }

        // Q_{θθ} = I_R + I_BB
        const Matrix3 Qtt = I_R + I_BB;

        // Q_{bb} = Qbg * Ts
        [[maybe_unused]] Matrix3 Qbb = Matrix3::Zero();
        if constexpr (with_gyro_bias) {
            Qbb = Qbg * Ts;
        }

        // Q_{θb} = (∫ B(s) ds) * Qbg    (closed form)
        [[maybe_unused]] Matrix3 Qtb = Matrix3::Zero();
        if constexpr (with_gyro_bias) {
            Matrix3 IB;
            integral_B_ds_(w, Ts, IB);
            Qtb = IB * Qbg;
        }

        // Pack into BASE_N × BASE_N
        Q_AA.template topLeftCorner<3,3>() = Qtt;
        if constexpr (with_gyro_bias) {
            Q_AA.template topRightCorner<3,3>()    = Qtb;
            Q_AA.template bottomLeftCorner<3,3>()  = Qtb.transpose();
            Q_AA.template bottomRightCorner<3,3>() = Qbb;
        }

        // Hygiene
        Q_AA = T(0.5) * (Q_AA + Q_AA.transpose());
        if constexpr (with_gyro_bias) {
            ocean_imu::kalman::ou_detail::project_psd_ou_iii<T,6>(Q_AA, T(1e-12));
        } else {
            ocean_imu::kalman::ou_detail::project_psd_ou_iii<T,3>(Q_AA, T(1e-12));
        }
    }

    // Always propagate attitude(+gyro-bias) covariance
    {
        constexpr int NA = BASE_N;
        MatrixBaseN& tmpAA = tmpAA_scratch_;
        tmpAA.noalias() = F_AA * Pext.template block<NA,NA>(0,0);
        Pext.template block<NA,NA>(0,0).noalias() = tmpAA * F_AA.transpose();
        Pext.template block<NA,NA>(0,0).noalias() += Q_AA;
    }

    // Linear subsystem [v,p,S,a_w] (12×12)
    Matrix12& F_LL = F_LL_scratch_; F_LL.setZero();
    Matrix12& Q_LL = Q_LL_scratch_; Q_LL.setZero();

    // Build F_LL per axis
    for (int axis = 0; axis < 3; ++axis) {
        const T tau = std::max(T(1e-6), tau_aw);

        Eigen::Matrix<T,4,4> Phi_axis;
        PhiAxis4x1_analytic(tau, Ts, Phi_axis);

        const int idx[4] = {0,3,6,9}; // [v,p,S,a] offsets
        for (int i = 0; i < 4; ++i)
            for (int j = 0; j < 4; ++j)
                F_LL(idx[i] + axis, idx[j] + axis) = Phi_axis(i,j);
    }
    // Build Q_LL
    if (aw_process_correlated_) {
        // Correlated vector-OU with shared tau: Q_LL = (Σ ⊗ Qaxis_unit)
        // written directly in group-first order: [v(3), p(3), S(3), a(3)].
        Eigen::Matrix<T,4,4> Qaxis_unit;
        QdAxis4x1_analytic(tau_aw, Ts, T(1), Qaxis_unit);
        Qaxis_unit = T(0.5) * (Qaxis_unit + Qaxis_unit.transpose()); // hygiene

        // SPD, symmetric copy of Σ_aw (3x3)
        const Matrix3 Sig = T(0.5) * (Sigma_aw_stat + Sigma_aw_stat.transpose());

        Q_LL.setZero();
        // group offsets in interleaved state order
        const int goff[4] = {0, 3, 6, 9}; // v, p, S, a

        // Blockwise assembly: each 3x3 block is Sig scaled by the 4x4 scalar
        for (int g = 0; g < 4; ++g) {
            for (int h = 0; h < 4; ++h) {
                Q_LL.template block<3,3>(goff[g], goff[h]).noalias()
                    = Sig * Qaxis_unit(g,h);
            }
        }
        // Symmetry + PSD cleanup
        Q_LL = T(0.5) * (Q_LL + Q_LL.transpose());
    } else {
        // Independent axes (no cross-correlation) — per-axis Qd on the diagonal
        const int idx[4] = {0,3,6,9};
        for (int axis = 0; axis < 3; ++axis) {
            const T tau    = std::max(T(1e-6), tau_aw);
            const T sigma2 = Sigma_aw_stat(axis, axis);
            Eigen::Matrix<T,4,4> Qd_axis;
            QdAxis4x1_analytic(tau, Ts, sigma2, Qd_axis);
            for (int i = 0; i < 4; ++i)
                for (int j = 0; j < 4; ++j)
                    Q_LL(idx[i] + axis, idx[j] + axis) = Qd_axis(i,j);
        }
        Q_LL = T(0.5) * (Q_LL + Q_LL.transpose());
    }

    // Mean propagation for [v,p,S,a_w]
    Vector12& x_lin_prev = x_lin_prev_scratch_;
    x_lin_prev.template segment<3>(0)  = xext.template segment<3>(OFF_V);
    x_lin_prev.template segment<3>(3)  = xext.template segment<3>(OFF_P);
    x_lin_prev.template segment<3>(6)  = xext.template segment<3>(OFF_S);
    x_lin_prev.template segment<3>(9)  = xext.template segment<3>(OFF_AW);

    Vector12& x_lin_next = x_lin_next_scratch_;
    // x_lin_next = F_LL * x_lin_prev.  Keep this in scalar loops instead
    // of an Eigen 12x12 expression to avoid cc1plus OOM on Arduino builds.
    for (int i = 0; i < 12; ++i) {
        T sum = T(0);
        for (int k = 0; k < 12; ++k) {
            sum += F_LL(i,k) * x_lin_prev(k);
        }
        x_lin_next(i) = sum;
    }
    xext.template segment<3>(OFF_V)  = x_lin_next.template segment<3>(0);
    xext.template segment<3>(OFF_P)  = x_lin_next.template segment<3>(3);
    xext.template segment<3>(OFF_S)  = x_lin_next.template segment<3>(6);
    xext.template segment<3>(OFF_AW) = x_lin_next.template segment<3>(9);

    // Covariance propagation (blockwise)
    constexpr int NA = BASE_N;
    constexpr int NL = 12;

    // LL block: P_LL_new = F_LL * P_LL_old * F_LLᵀ + Q_LL.
    // Written as loops to keep fixed-size Eigen template instantiations small.
    Matrix12& tmpLL = tmpLL_scratch_;
    for (int i = 0; i < NL; ++i) {
        for (int j = 0; j < NL; ++j) {
            T sum = T(0);
            for (int k = 0; k < NL; ++k) {
                sum += F_LL(i,k) * Pext(OFF_V + k, OFF_V + j);
            }
            tmpLL(i,j) = sum;
        }
    }
    for (int i = 0; i < NL; ++i) {
        for (int j = i; j < NL; ++j) {
            T sum = Q_LL(i,j);
            for (int k = 0; k < NL; ++k) {
                sum += tmpLL(i,k) * F_LL(j,k);
            }
            Pext(OFF_V + i, OFF_V + j) = sum;
            if (j != i) Pext(OFF_V + j, OFF_V + i) = sum;
        }
    }

    // AL block: P_AL_new = F_AA * P_AL_old * F_LLᵀ.
    MatrixBaseN12& tmpAL = tmpAL_scratch_;
    for (int i = 0; i < NA; ++i) {
        for (int j = 0; j < NL; ++j) {
            T sum = T(0);
            for (int k = 0; k < NA; ++k) {
                sum += F_AA(i,k) * Pext(k, OFF_V + j);
            }
            tmpAL(i,j) = sum;
        }
    }
    for (int i = 0; i < NA; ++i) {
        for (int j = 0; j < NL; ++j) {
            T sum = T(0);
            for (int k = 0; k < NL; ++k) {
                sum += tmpAL(i,k) * F_LL(j,k);
            }
            Pext(i, OFF_V + j) = sum;
            Pext(OFF_V + j, i) = sum;
        }
    }

    // Optional residual accel-bias OU and cross terms (F_BB = phi_b I)
    if constexpr (with_accel_bias) {
        constexpr int NB = 3;
        auto P_BB = Pext.template block<NB,NB>(OFF_BA,OFF_BA);
        const T tau_b = std::max(T(1e-3), tau_bacc_);
        const T phi_b = acc_bias_updates_enabled_ ? std::exp(-Ts / tau_b) : T(1);
        if (acc_bias_updates_enabled_) {
            // beta_a is the residual about the deterministic temperature mean.
            xext.template segment<3>(OFF_BA) *= phi_b;
            P_BB *= phi_b * phi_b;
            // Exact first-order Gauss--Markov covariance. Q_bacc_ is the
            // continuous driving spectral density, so this tends to
            // Q_bacc_*Ts as Ts/tau_b -> 0 and preserves the former
            // random-walk short-time diffusion calibration.
            const T qd_scale = -T(0.5) * tau_b * std::expm1(-T(2) * Ts / tau_b);
            P_BB.noalias() += Q_bacc_ * qd_scale;
        }
        Pext.template block<NB,NB>(OFF_BA,OFF_BA) = P_BB;

        Eigen::Matrix<T,NA,NB> tmpAB;
        for (int i = 0; i < NA; ++i) {
            for (int j = 0; j < NB; ++j) {
                T sum = T(0);
                for (int k = 0; k < NA; ++k) {
                    sum += F_AA(i,k) * Pext(k, OFF_BA + j);
                }
                tmpAB(i,j) = sum;
            }
        }
        tmpAB *= phi_b;
        Pext.template block<NA,NB>(0,OFF_BA) = tmpAB;
        Pext.template block<NB,NA>(OFF_BA,0) = tmpAB.transpose();

        Eigen::Matrix<T,NL,NB> tmpLB;
        for (int i = 0; i < NL; ++i) {
            for (int j = 0; j < NB; ++j) {
                T sum = T(0);
                for (int k = 0; k < NL; ++k) {
                    sum += F_LL(i,k) * Pext(OFF_V + k, OFF_BA + j);
                }
                tmpLB(i,j) = sum;
            }
        }
        tmpLB *= phi_b;
        Pext.template block<NL,NB>(OFF_V,OFF_BA) = tmpLB;
        Pext.template block<NB,NL>(OFF_BA,OFF_V) = tmpLB.transpose();
    }

    apply_pending_aw_covariance_inflation_();
    symmetrize_Pext_();   // Symmetry hygiene

    if (ocean_imu::kalman::ou_detail::periodic_update_due(Ts, pseudo_update_period_s_, pseudo_update_elapsed_s_)) {
        applyIntegralZeroPseudoMeas();
    }
}

template<typename T, bool with_gyro_bias, bool with_accel_bias>
void Kalman3D_Wave_OU_III<T, with_gyro_bias, with_accel_bias>::measurement_update_acc_only(
    Vector3 const& acc_meas_body, T tempC)
{
    last_acc_diag_ = MeasDiag3{};
    last_acc_diag_.accepted = false;

    // Reject invalid corrections before they can contaminate any mean/cross term.
    if (!acc_meas_body.allFinite() || !std::isfinite(tempC)) return;

    [[maybe_unused]] const bool use_ba = (with_accel_bias && acc_bias_updates_enabled_);

    // De-heel measured accel into B'
    const Vector3 acc_meas = deheel_vector_(acc_meas_body);

    // Physical accelerometer measurement model
    const Vector3 g_world(0,0,+gravity_magnitude_);

    // Lever-arm term (for non-full-model branches and J_bg)
    Vector3 lever = Vector3::Zero();
    if (use_imu_lever_arm_) {
        const Vector3& omega_bprime = last_gyr_bias_corrected; // ω^{B'}
        const Vector3& alpha_bprime = alpha_b_;                // α^{B'}
        const Vector3  r_imu_bprime = deheel_vector_(r_imu_wrt_cog_body_phys_);

        lever.noalias() += alpha_bprime.cross(r_imu_bprime)
                        +  omega_bprime.cross(omega_bprime.cross(r_imu_bprime));
    }

    Matrix3 J_bg = Matrix3::Zero();
    if constexpr (with_gyro_bias) {
        if (use_imu_lever_arm_) {
            const Vector3 r_imu_bprime = deheel_vector_(r_imu_wrt_cog_body_phys_);
            const Vector3& w = prev_omega_b_; // endpoint rate for lever-arm force

            // dω/db_g = -I
            // dα/db_g ≈ -(kα) I, with kα ~ 1/dt (or smoothed)
            T k_alpha = T(0);
            if (have_prev_omega_ && last_dt_ > T(0)) {
                if (alpha_smooth_tau_ > T(0)) {
                    const T a = T(1) - std::exp(-last_dt_ / alpha_smooth_tau_);
                    k_alpha = a / last_dt_;
                } else {
                    k_alpha = T(1) / last_dt_;
                }
            }
            // lever = α×r + ω×(ω×r)
            // ∂(α×r)/∂b_g = (+kα)[r]×    (since α depends on ω and ω depends on b_g)
            const Matrix3 J_alpha_part = k_alpha * skew_symmetric_matrix(r_imu_bprime);

            // ∂(ω×(ω×r))/∂b_g = - ∂(...)/∂ω
            const Matrix3 J_omega_part = d_omega_x_omega_x_r_domega_(w, r_imu_bprime);

            J_bg = J_alpha_part - J_omega_part;
        }
    }

    // Accel bias term (temp-dependent)
    Vector3 ba_term = Vector3::Zero();
    if constexpr (with_accel_bias) {
        const Vector3 ba0 = xext.template segment<3>(OFF_BA);
        // Always model BA in the mean (even if we freeze its estimation).
        ba_term = ba0 + k_a_ * (tempC - tempC_ref);
    }

    // Predicted specific force
    const Vector3 aw = xext.template segment<3>(OFF_AW);
    const Vector3 f_pred = R_wb() * (aw - g_world) + lever + ba_term;

    const Vector3& f_meas = acc_meas;
    const Vector3 r = f_meas - f_pred;

    last_acc_diag_.r = r;

    // Jacobians from linearization at CoG-only part (lever-arm is attitude-independent)
    const Vector3 f_cog_b = R_wb() * (aw - g_world);
    const Matrix3 J_att = -skew_symmetric_matrix(f_cog_b);
    const Matrix3 J_aw  =  R_wb();

    // Innovation covariance S = C P Cᵀ + Racc (3×3)
    Matrix3& S_mat = S_scratch_;
    S_mat = Racc;
    {
        constexpr int OFF_TH = 0;
        const int off_aw = OFF_AW;
        const int off_ba = OFF_BA;

        const Matrix3 P_th_th = Pext.template block<3,3>(OFF_TH, OFF_TH);
        S_mat.noalias() += J_att * P_th_th * J_att.transpose();

        {
            const Matrix3 P_th_aw = Pext.template block<3,3>(OFF_TH, off_aw);
            const Matrix3 P_aw_aw = Pext.template block<3,3>(off_aw,  off_aw);

            S_mat.noalias() += J_att * P_th_aw * J_aw.transpose();
            S_mat.noalias() += J_aw  * P_th_aw.transpose() * J_att.transpose();
            S_mat.noalias() += J_aw  * P_aw_aw * J_aw.transpose();
        }
		if constexpr (with_accel_bias) {
		    const Matrix3 P_ba_ba = Pext.template block<3,3>(off_ba, off_ba);
		    if (use_ba) {
		        const Matrix3 P_th_ba = Pext.template block<3,3>(OFF_TH, off_ba);

		        // J_ba = I
		        S_mat.noalias() += J_att * P_th_ba;
		        S_mat.noalias() += P_th_ba.transpose() * J_att.transpose();
		        S_mat.noalias() += P_ba_ba;

		        {
		            const Matrix3 P_aw_ba = Pext.template block<3,3>(off_aw, off_ba);
		            S_mat.noalias() += J_aw * P_aw_ba;
		            S_mat.noalias() += P_aw_ba.transpose() * J_aw.transpose();
		        }
		    } else {
		        // BA frozen: marginalize its uncertainty (and any existing cross-cov) into S.
		        // (If code already zeroed P_th_ba/P_aw_ba when disabling BA updates, these are 0 anyway.)
		        const Matrix3 P_th_ba = Pext.template block<3,3>(OFF_TH, off_ba);

		        // J_ba = I
		        S_mat.noalias() += J_att * P_th_ba;
		        S_mat.noalias() += P_th_ba.transpose() * J_att.transpose();

		        {
		            const Matrix3 P_aw_ba = Pext.template block<3,3>(off_aw, off_ba);
		            S_mat.noalias() += J_aw * P_aw_ba;
		            S_mat.noalias() += P_aw_ba.transpose() * J_aw.transpose();
		        }
		        S_mat.noalias() += P_ba_ba;
		    }
		}
        if constexpr (with_gyro_bias) {
            if (use_imu_lever_arm_) {
                constexpr int OFF_BG = 3;

                const Matrix3 P_th_bg = Pext.template block<3,3>(0, OFF_BG);
                const Matrix3 P_bg_bg = Pext.template block<3,3>(OFF_BG, OFF_BG);

                S_mat.noalias() += J_att * P_th_bg * J_bg.transpose();
                S_mat.noalias() += J_bg  * P_th_bg.transpose() * J_att.transpose();
                S_mat.noalias() += J_bg  * P_bg_bg * J_bg.transpose();

                {
                    const Matrix3 P_aw_bg = Pext.template block<3,3>(OFF_AW, OFF_BG);
                    S_mat.noalias() += J_aw * P_aw_bg * J_bg.transpose();
                    S_mat.noalias() += J_bg * P_aw_bg.transpose() * J_aw.transpose();
                }
                if constexpr (with_accel_bias) {
                    if (use_ba) {
                        const Matrix3 P_bg_ba = Pext.template block<3,3>(OFF_BG, OFF_BA);
                        S_mat.noalias() += J_bg * P_bg_ba; // J_ba = I
                        S_mat.noalias() += P_bg_ba.transpose() * J_bg.transpose();
                    }
                }
            }
        }
    }

    // PCᵀ = P Cᵀ (NX×3)
    MatrixNX3& PCt = PCt_scratch_; PCt.setZero();
    {
        constexpr int OFF_TH = 0;
        const auto P_all_th = Pext.template block<NX,3>(0, OFF_TH);
        PCt.noalias() += P_all_th * J_att.transpose();

        {
            const auto P_all_aw = Pext.template block<NX,3>(0, OFF_AW);
            PCt.noalias() += P_all_aw * J_aw.transpose();
        }
        if constexpr (with_accel_bias) {
            if (use_ba) {
                const auto P_all_ba = Pext.template block<NX,3>(0, OFF_BA);
                PCt.noalias() += P_all_ba; // J_ba = I
            }
        }
        if constexpr (with_gyro_bias) {
            if (use_imu_lever_arm_) {
                const auto P_all_bg = Pext.template block<NX,3>(0, 3);
                PCt.noalias() += P_all_bg * J_bg.transpose();
            }
        }
    }
    if constexpr (with_accel_bias) {
        if (!use_ba) freeze_acc_bias_rows_(PCt);
    }

    // Gain
    Eigen::LDLT<Matrix3> ldlt;
    if (!safe_ldlt3_(S_mat, ldlt, Racc.norm())) {
        // provide what we have
        last_acc_diag_.S = S_mat;
        last_acc_diag_.nis = std::numeric_limits<T>::quiet_NaN();
        last_acc_diag_.accepted = false;
        return;
    }
    // record final S + NIS
    last_acc_diag_.S = S_mat;
    last_acc_diag_.nis = nis3_from_ldlt_(ldlt, r);
    MatrixNX3& K = K_scratch_;
    gain_from_ldlt3_(PCt, ldlt, K);

    if constexpr (with_accel_bias) {
        if (!use_ba) freeze_acc_bias_rows_(K);
    }

    xext.noalias() += K * r;          // State update
    joseph_update3_(K, S_mat, PCt);   // Covariance update

    // Apply quaternion correction
    applyQuaternionCorrectionFromErrorState();
    last_acc_diag_.accepted = true;
}

template<typename T, bool with_gyro_bias, bool with_accel_bias>
void Kalman3D_Wave_OU_III<T, with_gyro_bias, with_accel_bias>::measurement_update_mag_only(
    const Vector3& mag_meas_body)
{
    last_mag_diag_ = MeasDiag3{};
    last_mag_diag_.accepted = false;

    // De-heel magnetometer into B'
    const Vector3 mag_meas = deheel_vector_(mag_meas_body);

    // Basic sanity gate
    if (!mag_meas.allFinite()) return;
    const T mag_norm = mag_meas.norm();
    if (!(mag_norm > T(1e-6))) return;

    // Predicted no-bias field for Jacobian.
    // Convention:
    //   qref  = WORLD->BODY'
    //   v2ref = WORLD-frame magnetic reference
    // So the predicted BODY' magnetometer measurement is +R_wb() * v2ref.
    const Vector3 v2hat = R_wb() * v2ref;

    const Vector3& zhat = v2hat;
    const Vector3 r = mag_meas - zhat;
    last_mag_diag_.r = r;

    // Jacobian uses the no-bias predicted vector
    const Matrix3 J_att = -skew_symmetric_matrix(v2hat);

    // Innovation covariance S = C P Cᵀ + R
    Matrix3& S_mat = S_scratch_;
    S_mat = Rmag;

    const Matrix3 P_th_th = Pext.template block<3,3>(0,0);
    S_mat.noalias() += J_att * P_th_th * J_att.transpose();


    // PCᵀ = P Cᵀ
    MatrixNX3& PCt = PCt_scratch_;
    PCt.setZero();
    PCt.noalias() += Pext.template block<NX,3>(0,0) * J_att.transpose();

    if constexpr (with_accel_bias) {
		if (!acc_bias_updates_enabled_) {
		    freeze_acc_bias_rows_(PCt);
		}
    }

    Eigen::LDLT<Matrix3> ldlt;
    if (!safe_ldlt3_(S_mat, ldlt, Rmag.norm())) {
        last_mag_diag_.S = S_mat;
        last_mag_diag_.nis = std::numeric_limits<T>::quiet_NaN();
        last_mag_diag_.accepted = false;
        return;
    }
    last_mag_diag_.S = S_mat;
    last_mag_diag_.nis = nis3_from_ldlt_(ldlt, r);

    MatrixNX3& K = K_scratch_;
    gain_from_ldlt3_(PCt, ldlt, K);

    if constexpr (with_accel_bias) {
		if (!acc_bias_updates_enabled_) {
		    freeze_acc_bias_rows_(K);
		}
    }

    // State + covariance update
    xext.noalias() += K * r;
    joseph_update3_(K, S_mat, PCt);
    applyQuaternionCorrectionFromErrorState();
	last_mag_diag_.accepted = true;
}

// specific force prediction (BODY'):
//   f_b' = R_wb (a_w − g) + α^{B'} × r_imu^{B'} + ω^{B'} × (ω^{B'} × r_imu^{B'}) + b_a(temp)
template<typename T, bool with_gyro_bias, bool with_accel_bias>
Eigen::Matrix<T,3,1>
Kalman3D_Wave_OU_III<T, with_gyro_bias, with_accel_bias>::accelerometer_measurement_func(T tempC) const {
    const Vector3 g_world(0,0,+gravity_magnitude_);
    const Vector3 aw = xext.template segment<3>(OFF_AW);

    // CoG specific force in B'
    const Vector3 f_cog_b = R_wb() * (aw - g_world);
    Vector3 fb = f_cog_b;

    // Optional IMU lever-arm correction:
    // Use ω^{B'}, α^{B'} and r_imu expressed in B' (via de-heel).
    if (use_imu_lever_arm_) {
        const Vector3& omega_bprime = last_gyr_bias_corrected; // ω^{B'}
        const Vector3& alpha_bprime = alpha_b_;                // α^{B'}
        const Vector3  r_imu_bprime = deheel_vector_(r_imu_wrt_cog_body_phys_);

        fb.noalias() += alpha_bprime.cross(r_imu_bprime)
                     +  omega_bprime.cross(omega_bprime.cross(r_imu_bprime));
    }
    if constexpr (with_accel_bias) {
        const Vector3 ba0 = xext.template segment<3>(OFF_BA);
        const Vector3 ba  = ba0 + k_a_ * (tempC - tempC_ref);
        fb += ba;
    }
    return fb;
}

// utility functions
template<typename T, bool with_gyro_bias, bool with_accel_bias>
Eigen::Matrix<T, 3, 3> Kalman3D_Wave_OU_III<T, with_gyro_bias, with_accel_bias>::skew_symmetric_matrix(const Eigen::Ref<const Vector3>& vec) const {
    Matrix3 M;
    M << 0, -vec(2), vec(1),
         vec(2), 0, -vec(0),
        -vec(1), vec(0), 0;
    return M;
}

template<typename T, bool with_gyro_bias, bool with_accel_bias>
void Kalman3D_Wave_OU_III<T, with_gyro_bias, with_accel_bias>::apply_error_state_reset_jacobian_(
    const Vector3& dtheta_injected)
{
    ocean_imu::kalman::ou_detail::apply_left_error_reset<T, NX>(Pext, dtheta_injected);
}

template<typename T, bool with_gyro_bias, bool with_accel_bias>
void Kalman3D_Wave_OU_III<T, with_gyro_bias, with_accel_bias>::applyQuaternionCorrectionFromErrorState()
{
    project_gyro_bias_();
    const Vector3 dtheta = xext.template segment<3>(0);

    if (!dtheta.allFinite()) {
        xext.template head<3>().setZero();
        return;
    }

    const Eigen::Quaternion<T> corr = ocean_imu::kalman::ou_detail::quat_from_delta_theta(dtheta);

    // qref stores WORLD->BODY'.
    // Measurement Jacobians use the left-multiplicative convention:
    //   z ≈ zhat - [zhat]x * delta_theta
    // so the correction must be injected on the LEFT.
    qref = corr * qref;
    qref.normalize();

    // Reset covariance consistently with the quaternion injection
    // before clearing the local attitude-error state.
    apply_error_state_reset_jacobian_(dtheta);

    // Clear the local attitude-error state after injection.
    xext.template head<3>().setZero();

    project_acc_bias_();
}

/*
  Project the accelerometer-bias estimate onto the ball of radius
  acc_bias_limit_. Called after every state injection, so the bound holds at
  all times. See set_accel_bias_limit().
*/
template<typename T, bool with_gyro_bias, bool with_accel_bias>
void Kalman3D_Wave_OU_III<T, with_gyro_bias, with_accel_bias>::project_acc_bias_()
{
    if constexpr (with_accel_bias) {
        if (!(acc_bias_limit_ > T(0))) return;

        auto b = xext.template segment<3>(OFF_BA);
        if (!b.allFinite()) { b.setZero(); return; }

        const T n = b.norm();
        if (n > acc_bias_limit_) {
            b *= (acc_bias_limit_ / n);
        }
    }
}

template<typename T, bool with_gyro_bias, bool with_accel_bias>
void Kalman3D_Wave_OU_III<T, with_gyro_bias, with_accel_bias>::applyIntegralZeroPseudoMeas()
{
    constexpr int off_S = OFF_S;   // offset of S block (3 states)

    // Innovation: target S = 0
    const Vector3 r = -xext.template segment<3>(off_S);

    // Innovation covariance S = P_SS + R_S
    Matrix3& S_mat = S_scratch_;
    S_mat = Pext.template block<3,3>(off_S, off_S) + R_S;

    // Cross covariance PCᵀ = P(:,S) (NX×3)
    MatrixNX3& PCt = PCt_scratch_;
    PCt.noalias() = Pext.template block<NX,3>(0, off_S);
	if constexpr (with_accel_bias) {
        if (!acc_bias_updates_enabled_) freeze_acc_bias_rows_(PCt);
    }

    Eigen::LDLT<Matrix3> ldlt;
    if (!safe_ldlt3_(S_mat, ldlt, R_S.norm())) return;
    MatrixNX3& K = K_scratch_;
    gain_from_ldlt3_(PCt, ldlt, K);
    if constexpr (with_accel_bias) {
        if (!acc_bias_updates_enabled_) freeze_acc_bias_rows_(K);
    }

    xext.noalias() += K * r;            // State update
    joseph_update3_(K, S_mat, PCt);     // Covariance update

    // Apply quaternion correction (attitude may get nudged via cross-covariances)
    applyQuaternionCorrectionFromErrorState();
}

template<typename T, bool with_gyro_bias, bool with_accel_bias>
void Kalman3D_Wave_OU_III<T, with_gyro_bias, with_accel_bias>::measurement_update_position_pseudo(
    const Vector3& p_meas, const Vector3& sigma_meas)
{
	constexpr int off_P = OFF_P; // position block

    // Predicted position (world, NED)
    const Vector3 p_pred = xext.template segment<3>(off_P);
    Vector3 r = p_meas - p_pred;          // innovation (meters)

    if (!r.allFinite()) {
        return;
    }

    // Innovation covariance S = H P Hᵀ + R, with H selecting the p-block.
    // Here H is [0 ... I_3 ... 0], so:
    //
    //   S = P_pp + R
    //
    Matrix3& S_mat = S_scratch_;
    S_mat = Pext.template block<3,3>(off_P, off_P);

    Matrix3 R_meas = Matrix3::Zero();
    const T sx = std::max(T(0), sigma_meas.x());
    const T sy = std::max(T(0), sigma_meas.y());
    const T sz = std::max(T(0), sigma_meas.z());
    R_meas(0,0) = sx * sx;
    R_meas(1,1) = sy * sy;
    R_meas(2,2) = sz * sz;
    S_mat.noalias() += R_meas;

    // Cross-covariance PCᵀ = P(:,p) (N×3)
    MatrixNX3& PCt = PCt_scratch_;
    PCt.noalias() = Pext.template block<NX,3>(0, off_P);

    // Gain K = PCᵀ S⁻¹
    Eigen::LDLT<Matrix3> ldlt;
    const T noise_scale = R_meas.norm();
    if (!safe_ldlt3_(S_mat, ldlt, noise_scale)) {
        return;
    }

    MatrixNX3& K = K_scratch_;
    gain_from_ldlt3_(PCt, ldlt, K);

    xext.noalias() += K * r;           // State update
    joseph_update3_(K, S_mat, PCt);    // Covariance update (Joseph form, 3D)

    // Attitude may have been nudged via cross-covariance → apply correction
    applyQuaternionCorrectionFromErrorState();
}

template<typename T, bool with_gyro_bias, bool with_accel_bias>
void Kalman3D_Wave_OU_III<T, with_gyro_bias, with_accel_bias>::measurement_update_velocity_pseudo(
    const Vector3& v_meas, const Vector3& sigma_meas)
{
    constexpr int off_V = OFF_V; // velocity block

    const Vector3 v_pred = xext.template segment<3>(off_V);
    const Vector3 r = v_meas - v_pred; // innovation (m/s)
    if (!r.allFinite()) {
        return;
    }

    Matrix3& S_mat = S_scratch_;
    S_mat = Pext.template block<3,3>(off_V, off_V);

    Matrix3 R_meas = Matrix3::Zero();
    const T sx = std::max(T(0), sigma_meas.x());
    const T sy = std::max(T(0), sigma_meas.y());
    const T sz = std::max(T(0), sigma_meas.z());
    R_meas(0,0) = sx * sx;
    R_meas(1,1) = sy * sy;
    R_meas(2,2) = sz * sz;
    S_mat.noalias() += R_meas;

    MatrixNX3& PCt = PCt_scratch_;
    PCt.noalias() = Pext.template block<NX,3>(0, off_V);

    Eigen::LDLT<Matrix3> ldlt;
    const T noise_scale = R_meas.norm();
    if (!safe_ldlt3_(S_mat, ldlt, noise_scale)) {
        return;
    }

    MatrixNX3& K = K_scratch_;
    gain_from_ldlt3_(PCt, ldlt, K);

    xext.noalias() += K * r;
    joseph_update3_(K, S_mat, PCt);

    applyQuaternionCorrectionFromErrorState();
}

template<typename T, bool with_gyro_bias, bool with_accel_bias>
void Kalman3D_Wave_OU_III<T, with_gyro_bias, with_accel_bias>::measurement_update_vert_velocity_pseudo(
    T vz_meas, T sigma_meas)
{
    constexpr int idx_vz = OFF_V + 2; // z (down) axis in NED

    if (!std::isfinite(vz_meas)) {
        return;
    }

    const T r = vz_meas - xext(idx_vz);
    if (!std::isfinite(r)) {
        return;
    }

    const T sigma = std::max(T(0), sigma_meas);
    const T R = sigma * sigma;
    const T S = Pext(idx_vz, idx_vz) + R;

    if (!(S > T(0)) || !std::isfinite(S)) {
        return;
    }

    Eigen::Matrix<T, NX, 1> PCt;
    for (int i = 0; i < NX; ++i) {
        PCt(i) = Pext(i, idx_vz);
    }

    Eigen::Matrix<T, NX, 1> K;
    for (int i = 0; i < NX; ++i) {
        K(i) = PCt(i) / S;
        xext(i) += K(i) * r;
    }

    // Joseph-form scalar update: P = P - K*PCt' - PCt*K' + K*S*K'.
    // Scalar loops avoid instantiating several NX×NX Eigen outer products.
    for (int i = 0; i < NX; ++i) {
        for (int j = i; j < NX; ++j) {
            const T updated = Pext(i,j)
                - K(i) * PCt(j)
                - PCt(i) * K(j)
                + K(i) * S * K(j);
            Pext(i,j) = updated;
            if (j != i) Pext(j,i) = updated;
        }
    }

    applyQuaternionCorrectionFromErrorState();
}

template<typename T, bool with_gyro_bias, bool with_accel_bias>
void Kalman3D_Wave_OU_III<T, with_gyro_bias, with_accel_bias>::PhiAxis4x1_analytic(
    T tau, T h, Eigen::Matrix<T,4,4>& Phi_axis)
{
    ocean_imu::kalman::ou_detail::IntegratedOUChain<T, 3>::transition(tau, h, Phi_axis);
}

// Discrete OU covariance for [v, p, S, a] axis subsystem.
// Inputs:
//   tau     = OU correlation time constant [s]
//   h       = step size (sampling interval Ts) [s]
//   sigma2  = stationary variance of a [ (m/s^2)^2 ]
// Outputs:
//   Qd_axis = (4x4) discrete covariance contribution for [v, p, S, a]
template<typename T, bool with_gyro_bias, bool with_accel_bias>
void Kalman3D_Wave_OU_III<T, with_gyro_bias, with_accel_bias>::QdAxis4x1_analytic(
    T tau, T h, T sigma2, Eigen::Matrix<T,4,4>& Qd_axis)
{
    ocean_imu::kalman::ou_detail::IntegratedOUChain<T, 3>::process_covariance(
        tau, h, sigma2, Qd_axis);
}

} // namespace ocean_imu::kalman

// Source compatibility for existing callers of the unqualified name.
using ocean_imu::kalman::Kalman3D_Wave_OU_III;

